  @override
  String get inhalantsMilestone30Title => 'Satu Bulan — Otak Terus Pulih';

  @override
  String get inhalantsMilestone30Description =>
      'Setelah satu bulan, efek awal yang paling berat sudah terlewati dan kemampuan berpikir serta ingatan mulai pulih. Kejernihan pikiran dan suasana hati membaik.';

  @override
  String get inhalantsMilestone90Title => 'Tiga Bulan — Pemulihan Berlanjut';

  @override
  String get inhalantsMilestone90Description =>
      'Tiga bulan tanpa inhalansia mendukung pemulihan berkelanjutan pada ingatan, perhatian, dan fungsi motorik. Perbaikannya bertahap, tetapi nyata.';

  @override
  String get inhalantsMilestone365Title => 'Satu Tahun — Pemulihan Besar';

  @override
  String get inhalantsMilestone365Description =>
      'Satu tahun tanpa inhalansia membawa pemulihan neurologis yang besar bagi kebanyakan orang, dengan kemajuan yang diperkirakan terus berlanjut pada tahun kedua.';

  @override
  String get inhalantsMilestone730Title =>
      'Dua Tahun — Pemulihan Jangka Panjang';

  @override
  String get inhalantsMilestone730Description =>
      'Setelah dua tahun abstinensi, penelitian menemukan pemulihan besar pada fungsi otak. Kerusakan akibat bensin bertimbal merupakan pengecualian dan dapat menetap.';

  @override
  String get synthetic_cannabinoidsPageTitle => 'Kanabinoid Sintetis';

  @override
  String get synthetic_cannabinoidsHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get synthetic_cannabinoidsHeaderNotStarted =>
      'Manfaat Berhenti dari Cannabinoid Sintetis';

  @override
  String get synthetic_cannabinoidsSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get synthetic_cannabinoidsSubtitleNotStarted =>
      'Lihat apa yang terjadi ketika Anda berhenti';

  @override
  String get synthetic_cannabinoidsInfoBox =>
      'Kanabinoid sintetis (“Spice”, “K2”) dapat jauh lebih kuat dan tidak terduga dibanding ganja. Putus zat dapat lebih berat, dengan laporan kejang, agitasi, dan detak jantung cepat; keracunan akut juga dapat menyebabkan psikosis. Gejala berat memerlukan pertolongan medis segera.';

  @override
  String get addictionSyntheticCannabinoids => 'Cannabinoid Sintetis';

  @override
  String get synthetic_cannabinoidsMilestone1Title => 'Putus Zat Dimulai';

  @override
  String get synthetic_cannabinoidsMilestone1Description =>
      'Putus zat dapat muncul cepat setelah penggunaan yang sering. Gangguan tidur, mudah marah, suasana hati rendah, berkeringat, jantung berdebar, agitasi, dan gemetar semuanya dilaporkan — kasus berat dapat mencakup kejang berulang atau masalah kardiovaskular atau pernapasan.';

  @override
  String get synthetic_cannabinoidsMilestone3Title => 'Masa Awal yang Berat';

  @override
  String get synthetic_cannabinoidsMilestone3Description =>
      'Tiga hari bersih. Putus zat kanabinoid sintetis dapat lebih berat daripada ganja berpotensi tinggi, jadi fase awal ini serius. Anda sudah menciptakan jarak nyata dari dosis berikutnya.';

  @override
  String get synthetic_cannabinoidsMilestone7Title => 'Satu Minggu Kuat';

  @override
  String get synthetic_cannabinoidsMilestone7Description =>
      'Satu minggu kuat. Putus zat kanabinoid sintetis dapat berat dan lebih bersifat fisik dibanding putus ganja. Tujuh hari tanpa dosis lagi adalah kemenangan besar.';

  @override
  String get synthetic_cannabinoidsMilestone14Title => 'Dua Minggu Bersih';

  @override
  String get synthetic_cannabinoidsMilestone14Description =>
      'Dua minggu bersih. Kanabinoid sintetis memang berbeda: Anda sudah melewati empat belas hari tanpa terpapar lagi pada golongan zat yang terkait dengan kejang, psikosis, dan masalah jantung.';

  @override
  String get synthetic_cannabinoidsMilestone30Title => 'Sebulan Bebas';

  @override
  String get synthetic_cannabinoidsMilestone30Description =>
      'Satu bulan penuh bersih. Tiga puluh hari tanpa terpapar lagi pada potensi yang tidak terduga dan toksisitas akut kanabinoid sintetis. Tonggak yang besar.';

  @override
  String get synthetic_cannabinoidsMilestone90Title => 'Tiga Bulan Bebas';

  @override
  String get synthetic_cannabinoidsMilestone90Description =>
      'Tiga bulan bebas. Anda sudah memberi jarak lebar dari golongan zat yang terkait dengan putus zat berat, kejang, masalah kardiovaskular, dan psikosis. Terus lanjutkan.';

  @override
  String get synthetic_cannabinoidsMilestone180Title => 'Setengah Tahun Bebas';

  @override
  String get synthetic_cannabinoidsMilestone180Description =>
      'Setengah tahun bebas. Enam bulan tanpa kanabinoid sintetis adalah pencapaian besar — enam bulan tanpa menghadapi lagi risiko akutnya yang tidak terduga.';

  @override
  String get synthetic_cannabinoidsWithdrawalReference =>
      'Putus zat kanabinoid sintetis\n\nSumber: Craft et al. (2022), Psychopharmacology, PMC\n\nDari 284 orang yang memakai agonis reseptor kanabinoid sintetis lebih dari sepuluh kali pada tahun sebelumnya dan pernah mencoba berhenti, 82,7% melaporkan setidaknya satu gejala putus zat setelah lebih dari satu hari tanpa penggunaan. Yang paling sering adalah gangguan tidur (59,2%), mudah marah (55,6%), dan suasana hati rendah (54,2%); keringat, jantung berdebar, keinginan memakai, agitasi, dan gemetar juga dilaporkan. Penggunaan yang lebih sering dan lebih banyak berkaitan dengan lebih banyak gejala. Dalam perbandingan langsung, putus zat kanabinoid sintetis dinilai lebih berat daripada putus ganja berpotensi tinggi.';

  @override
  String get synthetic_cannabinoidsRiskReference =>
      'Putus zat dan risiko akut kanabinoid sintetis\n\nSumber: Cooper (2016), Current Psychiatry Reports, PMC\n\nLaporan klinis menggambarkan putus zat setelah penggunaan harian yang dapat muncul segera setelah dosis terakhir, dengan kecemasan berat, insomnia, mual dan muntah, keringat, jantung berdebar, tremor, agitasi, dan keinginan memakai. Kasus berat mencakup kejang berulang serta masalah kardiovaskular atau pernapasan. Tinjauan ini juga menggambarkan keracunan yang tidak terduga dan kadang berat, termasuk psikosis, kejang, kejadian jantung, dan cedera ginjal. Gejala berat atau yang memburuk memerlukan penilaian medis segera.';

  @override
  String get synthetic_cannabinoidsMilestone730Title =>
      'Dua Tahun — Landasan Kokoh';

  @override
  String get synthetic_cannabinoidsMilestone730Description =>
      'Dua tahun bebas dari kanabinoid sintetis. Kamu sudah membangun 730 hari tanpa kembali menggunakannya. Konsistensi ini layak dirayakan.';

  @override
  String get synthetic_cannabinoidsMilestone1095Title =>
      'Tiga Tahun — Tetap Kuat';

  @override
  String get synthetic_cannabinoidsMilestone1095Description =>
      'Tiga tahun bebas dari kanabinoid sintetis. Perubahan ini sekarang dihitung dalam tahun, bukan hari. Kamu terus melangkah maju.';

  @override
  String get synthetic_cannabinoidsMilestone1460Title =>
      'Empat Tahun — Bertahan Lama';

  @override
  String get synthetic_cannabinoidsMilestone1460Description =>
      'Empat tahun bebas dari kanabinoid sintetis. Berhenti telah menjadi sesuatu yang bertahan: 1.460 hari menjauh darinya.';

  @override
  String get synthetic_cannabinoidsMilestone1825Title =>
      'Lima Tahun — Setengah Dekade';

  @override
  String get synthetic_cannabinoidsMilestone1825Description =>
      'Lima tahun bebas dari kanabinoid sintetis. Setengah dekade adalah kemenangan jangka panjang yang besar. Kemajuan ini milikmu.';

  @override
  String get synthetic_cannabinoidsLongTermReference =>
      'Kanabinoid sintetis: apa yang didukung bukti\n\nSumber: pedoman konsensus British Association for Psychopharmacology tentang ketergantungan zat (2026), PMC\n\nPedoman menyatakan bahwa kanabinoid sintetis dapat menimbulkan sindrom putus zat yang lebih berat daripada kanabis dan mungkin memerlukan detoksifikasi rawat inap. Pedoman juga menyatakan belum ada farmakoterapi berbasis bukti untuk pemeliharaan atau pencegahan kekambuhan pada penggunaan kanabinoid sintetis.\n\nPedoman tidak menetapkan ambang pemulihan biologis pada 2, 3, 4, atau 5 tahun. Karena itu, tonggak ini merayakan kemajuan yang bertahan tanpa mengklaim batas waktu medis yang tidak didukung bukti.';

  @override
  String get mdmaPageTitle => 'Pemulihan MDMA';

  @override
  String get mdmaHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get mdmaHeaderNotStarted => 'Manfaat Berhenti dari MDMA';

  @override
  String get mdmaSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get mdmaSubtitleNotStarted =>
      'Lihat apa yang terjadi ketika Anda berhenti';

  @override
  String get mdmaInfoBox =>
      'MDMA membanjiri dan kemudian menghabiskan serotonin, menghasilkan “comedown” dan, setelah penggunaan yang berlebihan, suasana hati yang buruk seperti penarikan diri. Tingkat transporter serotonin pulih dengan pantang terus-menerus, meskipun penggunaan berlebihan dapat meninggalkan efek yang bertahan lebih lama.';

  @override
  String get addictionMdma => 'MDMA';

  @override
  String get mdmaMilestone1Title => 'Fase Comedown';

  @override
  String get mdmaMilestone1Description =>
      'Setelah MDMA, penurunan serotonin memicu fase “comedown”: suasana hati menurun, lelah, mudah tersinggung, dan tidur terganggu selama satu atau dua hari. Cukup minum, makan, dan beristirahat dapat membantu.';

  @override
  String get mdmaMilestone3Title => 'Suasana Hati Mulai Seimbang';

  @override
  String get mdmaMilestone3Description =>
      'Setelah beberapa hari, bagian paling berat dari comedown biasanya sudah lewat. Suasana hati dan energi mulai kembali seimbang seiring serotonin pulih.';

  @override
  String get mdmaMilestone7Title => 'Fase Akut Berakhir';

  @override
  String get mdmaMilestone7Description =>
      'Setelah penggunaan yang lebih berat, gejala mirip putus zat seperti suasana hati rendah, sulit fokus, dan keinginan memakai lagi dapat berlangsung sekitar satu minggu sebelum membaik.';

  @override
  String get mdmaMilestone14Title => 'Dua Minggu Berlalu';

  @override
  String get mdmaMilestone14Description =>
      'Dua minggu tanpa MDMA biasanya membawa perbaikan nyata pada suasana hati, tidur, dan fokus seiring sistem serotonin pulih.';

  @override
  String get mdmaMilestone30Title => 'Satu Bulan Tanpa MDMA';

  @override
  String get mdmaMilestone30Description =>
      'Setelah satu bulan, suasana hati dan pikiran jauh lebih stabil. Sistem daur ulang serotonin di otak terus pulih selama Anda tetap tidak menggunakan MDMA.';

  @override
  String get mdmaMilestone90Title => 'Tiga Bulan Berlalu';

  @override
  String get mdmaMilestone90Description =>
      'Tiga bulan tanpa MDMA mendukung pemulihan lanjutan sistem serotonin. Suasana hati dan tidur sudah stabil; kecemasan biasanya berkurang pada bulan-bulan berikutnya.';

  @override
  String get mdmaMilestone365Title => 'Satu Tahun Tanpa MDMA';

  @override
  String get mdmaMilestone365Description =>
      'Satu tahun tanpa MDMA. Fungsi serotonin dan suasana hati telah mendapat waktu panjang untuk pulih, dan kecemasan terkait penggunaan biasanya sudah mereda.';

  @override
  String get steroidsPageTitle => 'Steroid Anabolik';

  @override
  String get steroidsHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get steroidsHeaderNotStarted =>
      'Manfaat Berhenti dari Steroid Anabolik';

  @override
  String get steroidsSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get steroidsSubtitleNotStarted =>
      'Lihat apa yang terjadi ketika Anda berhenti';

  @override
  String get steroidsInfoBox =>
      'Menghentikan steroid anabolik akan menyebabkan kadar testosteron rendah hingga tubuh memulai kembali produksi hormonnya sendiri – biasanya dalam waktu berbulan-bulan, namun terkadang lebih lama. Depresi dan libido rendah sering terjadi selama fase ini; depresi berat atau pikiran untuk bunuh diri memerlukan perawatan medis segera.';

  @override
  String get addictionSteroids => 'Steroid Anabolik';

  @override
  String get steroidsMilestone1Title => 'Defisit Hormon Dimulai';

  @override
  String get steroidsMilestone1Description =>
      'Steroid anabolik menekan testosteron tubuh Anda sendiri. Saat berhenti, Anda mengalami defisit hormon, yang dapat menyebabkan kelelahan, suasana hati yang buruk, dan libido yang rendah. Bimbingan medis dianjurkan.';

  @override
  String get steroidsMilestone14Title => 'Fase Penyesuaian';

  @override
  String get steroidsMilestone14Description =>
      'Minggu-minggu pertama adalah masa penurunan hormon yang paling sulit - energi, suasana hati, dan libido yang rendah. Ini adalah fase di mana banyak orang kambuh untuk menghindarinya; dukungan membantu.';

  @override
  String get steroidsMilestone30Title => 'Satu Bulan — Sumbu Mulai Pulih';

  @override
  String get steroidsMilestone30Description =>
      'Dalam sebulan, sistem hormon otak-testis Anda dimulai kembali. Hormon-hormon yang mendorong testosteron dan testosteron itu sendiri mulai meningkat, meski suasana hati, libido, atau energi yang rendah masih bisa bertahan.';

  @override
  String get steroidsMilestone90Title => 'Tiga Bulan - Peningkatan Hormon';

  @override
  String get steroidsMilestone90Description =>
      'Tiga bulan kemudian, testosteron dan hormon-hormon yang mendorongnya meningkat ke arah normal bagi kebanyakan orang, dan suasana hati serta libido sering kali membaik seiring dengan itu.';

  @override
  String get steroidsMilestone180Title => 'Enam Bulan — Pemulihan Maju';

  @override
  String get steroidsMilestone180Description =>
      'Dalam enam bulan, banyak orang mengalami pemulihan hormon yang kuat, dengan testosteron dan hormon pengontrolnya kembali normal dan gejalanya mereda.';

  @override
  String get steroidsMilestone365Title => 'Satu Tahun';

  @override
  String get steroidsMilestone365Description =>
      'Setahun penuh tanpa steroid adalah pencapaian besar. Pemulihan hormon sering berlangsung selama berbulan-bulan, sementara ukuran testis, produksi sperma, dan libido dapat terus membaik selama berbulan-bulan hingga bertahun-tahun. Gejala testosteron rendah yang menetap layak dinilai oleh spesialis.';

  @override
  String get steroidsMilestone730Title => 'Dua Tahun — Keadaan Normal Baru';

  @override
  String get steroidsMilestone730Description =>
      'Dua tahun tanpa steroid. Pemulihan setelah AAS berbeda-beda, tetapi sistem hormon alami tubuh Anda sudah mendapat waktu yang panjang untuk pulih. Jika gejala testosteron rendah masih menetap, periksakan ke spesialis daripada kembali menjalani siklus lain.';

  @override
  String get appTitle => 'Berhenti';

  @override
  String get start => 'Awal';

  @override
  String get tabQuitter => 'Berhenti';

  @override
  String get adderallPageTitle => 'Keluar dari Adderall';

  @override
  String get adderallHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get adderallHeaderNotStarted => 'Siap Memulai Pemulihan Anda?';

  @override
  String get adderallSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian saat otak Anda pulih';

  @override
  String get adderallSubtitleNotStarted =>
      'Lihat apa yang terjadi ketika Anda keluar dari Adderall dan memulai perjalanan Anda menuju pemulihan';

  @override
  String get adderallMilestone1Title =>
      '24 Jam Pertama: Gejala Putus Zat Dimulai';

  @override
  String get adderallMilestone1Description =>
      'Anda mungkin merasa semakin lelah, depresi, dan nafsu makan saat tubuh Anda mulai menyesuaikan diri dengan kehidupan tanpa stimulan. Ini normal dan bersifat sementara. Tetap terhidrasi dan istirahat bila diperlukan.';

  @override
  String get adderallMilestone3Title => 'Hari ke-3: Puncak Gejala Putus Zat';

  @override
  String get adderallMilestone3Description =>
      'Gejala putus zat mencapai intensitas puncaknya. Anda mungkin mengalami kelelahan yang parah, mudah tersinggung, dan kesulitan berkonsentrasi. Ini adalah bagian tersulit - tetapi mulai sekarang akan menjadi lebih baik. Pertimbangkan untuk menghubungi sistem pendukung Anda.';

  @override
  String get adderallMilestone7Title => 'Satu Minggu: Gejala Fisik Membaik';

  @override
  String get adderallMilestone7Description =>
      'Gejala fisik putus zat yang terburuk mulai memudar. Pola tidur mulai normal dan tingkat energi perlahan membaik. Tubuh Anda beradaptasi untuk berfungsi tanpa stimulan.';

  @override
  String get adderallMilestone14Title =>
      'Dua Minggu: Stabilitas Emosional Kembali';

  @override
  String get adderallMilestone14Description =>
      'Perubahan suasana hati dan mudah tersinggung berkurang. Anda mendapatkan kembali keseimbangan emosional seiring dengan stabilnya kimia otak Anda. Banyak orang mendapati minggu ini menandai titik balik dalam perjalanan pemulihan mereka.';

  @override
  String get adderallMilestone30Title =>
      'Satu Bulan: Penyeimbangan Kembali Kimia Otak';

  @override
  String get adderallMilestone30Description =>
      'Otak Anda secara aktif melakukan penyembuhan. Produksi dopamin alami meningkat, dan Anda mungkin merasakan fokus dan motivasi yang lebih baik tanpa pengobatan. Kualitas tidur dan nafsu makan kembali ke pola normal.';

  @override
  String get adderallMilestone60Title =>
      'Dua Bulan: Berpikir dan Ingatan Meningkat';

  @override
  String get adderallMilestone60Description =>
      'Peningkatan signifikan dalam kejernihan mental, memori, dan stabilitas suasana hati. Sistem penghargaan otak Anda sedang dalam proses penyembuhan, membuat aktivitas sehari-hari menjadi lebih bermanfaat secara alami. Banyak orang melaporkan merasa lebih seperti diri mereka sendiri.';

  @override
  String get adderallMilestone90Title => 'Tiga Bulan: Tonggak Pemulihan Besar';

  @override
  String get adderallMilestone90Description =>
      'Sebagian besar gejala putus zat telah teratasi. Otak Anda telah membuat kemajuan besar dalam penyembuhan. Tingkat energi alami, fokus, dan pengaturan emosi meningkat secara signifikan. Ini merupakan pencapaian besar yang patut dirayakan.';

  @override
  String get adderallMilestone180Title =>
      'Enam Bulan: Penyembuhan Otak Berlanjut';

  @override
  String get adderallMilestone180Description =>
      'Sinyal dopamin terus pulih. Fokus, ingatan, suasana hati, dan kualitas hidup sehari-hari terus meningkat.';

  @override
  String get adderallMilestone365Title =>
      'Satu Tahun: Pemulihan Hampir Selesai';

  @override
  String get adderallMilestone365Description =>
      'Sistem dopamin otak Anda sebagian besar telah kembali berfungsi normal. Anda telah membuktikan ketahanan Anda dan membangun kembali hidup Anda tanpa ketergantungan pada stimulan. Pencapaian ini mewakili transformasi menyeluruh - rayakan seberapa jauh kemajuan Anda!';

  @override
  String get benzoPageTitle => 'Benzodiazepin';

  @override
  String get benzoHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get benzoHeaderNotStarted => 'Manfaat Berhenti dari Benzodiazepin';

  @override
  String get benzoSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get benzoSubtitleNotStarted =>
      'Lihat apa yang terjadi ketika Anda berhenti';

  @override
  String get benzoMilestone7Title => 'Minggu Pertama: Jendela Awal Lengkap';

  @override
  String get benzoMilestone7Description =>
      'Pada hari ke-7, seluruh jendela awal yang umum sudah tercakup: putus benzodiazepin kerja singkat biasanya mulai 1–2 hari setelah dosis terakhir, sedangkan yang kerja panjang 2–7 hari. Penurunan dosis bertahap penting karena membantu mencegah kejang.';

  @override
  String get benzoMilestone14Title => 'Dua Minggu: Tidur Nyenyak Pulih';

  @override
  String get benzoMilestone14Description =>
      'Sekitar dua minggu setelah penghentian benzodiazepin secara bertahap, sebuah studi tidur klinis menemukan peningkatan tidur gelombang lambat dan kualitas tidur yang dirasakan. Ini adalah tanda pemulihan awal yang nyata pada sistem tidur.';

  @override
  String get benzoMilestone60Title => '8 Minggu: Fokus dan Keseimbangan';

  @override
  String get benzoMilestone60Description =>
      'Dalam studi 8 minggu pada pengguna lama obat tidur benzodiazepin yang lebih tua, peserta yang menyelesaikan penurunan dosis hingga berhenti menunjukkan peningkatan pada memori langsung, perhatian, skor bahasa, dan kestabilan tubuh. Ini pemulihan fungsi siang hari yang terukur.';

  @override
  String get benzoMilestone90Title => 'Tiga Bulan: Pikiran Lebih Cepat';

  @override
  String get benzoMilestone90Description =>
      'Pada 12 minggu setelah taper selesai, pengguna benzodiazepin jangka panjang yang berhasil berhenti menyelesaikan tugas kognitif berkecepatan lebih cepat dan melaporkan sedasi mental serta fisik yang lebih ringan dibanding orang yang masih memakai benzodiazepin. Itu adalah pemulihan fungsi siang hari yang terukur.';

  @override
  String get benzoMilestone180Title => 'Pemikiran dan Ingatan Mulai Pulih';

  @override
  String get benzoMilestone180Description =>
      'Pada enam bulan, ingatan dan perhatian menunjukkan peningkatan yang terukur. Penelitian menemukan pemulihan pada banyak keterampilan berpikir, dan kemajuan terus berlanjut setelah enam bulan.';

  @override
  String get benzoMilestone365Title => 'Satu Tahun Penyembuhan';

  @override
  String get benzoMilestone365Description =>
      'Setelah satu tahun, peningkatan signifikan dalam kesejahteraan mental dan fisik mulai terlihat. Banyak yang melaporkan berkurangnya kecemasan, kualitas tidur lebih baik, dan peningkatan kesehatan secara keseluruhan dibandingkan dengan penggunaan benzodiazepin dalam jangka panjang. Penyembuhan otak berlanjut.';

  @override
  String get benzoMilestone540Title => 'Pemulihan Otak Berkelanjutan';

  @override
  String get benzoMilestone540Description =>
      'Pada usia 18 bulan, ingatan, perhatian, dan pemikiran jernih terus meningkat. Sistem GABA yang menenangkan di otak membutuhkan waktu lebih dari satu tahun untuk menetap, sementara otak terus membangun pola yang lebih sehat.';

  @override
  String get benzoMilestone730Title => 'Dua Tahun: Kemajuan Besar';

  @override
  String get benzoMilestone730Description =>
      'Dua tahun menandai pemulihan substansial. Kebanyakan orang memiliki pemikiran yang lebih jernih, emosi yang lebih stabil, dan kualitas hidup yang jauh lebih baik dibandingkan dengan penggunaan benzodiazepin jangka panjang.';

  @override
  String get benzoMilestone1095Title => 'Tiga Tahun: Pemulihan Jangka Panjang';

  @override
  String get benzoMilestone1095Description =>
      'Dalam tiga tahun, periode penarikan yang lama jauh tertinggal dari kebanyakan orang. Tidur, suasana hati, ingatan, dan perhatian membutuhkan waktu bertahun-tahun untuk pulih, dan kehidupan sehari-hari biasanya jauh lebih baik dibandingkan penggunaan jangka panjang.';

  @override
  String get benzoMilestone1460Title => 'Empat Tahun: Kemajuan Mantap';

  @override
  String get benzoMilestone1460Description =>
      'Empat tahun tanpa benzodiazepin adalah perjalanan pemulihan panjang yang dibangun hari demi hari. Karena waktunya berbeda untuk setiap orang, peringatan ini merayakan kestabilan, rutinitas, dan ketangguhan yang telah diperkuat tanpa menganggap ada satu garis akhir bagi semua orang.';

  @override
  String get benzoMilestone1825Title => 'Lima Tahun: Fondasi Kuat';

  @override
  String get benzoMilestone1825Description =>
      'Lima tahun adalah pencapaian jangka panjang yang besar. Pemulihan tidak mengikuti satu jadwal, tetapi lima tahun perubahan yang bertahan berarti ribuan hari latihan, dukungan, dan kehidupan yang dibangun melampaui benzodiazepin.';

  @override
  String get addictionMeth => 'Met';

  @override
  String get addictionBenzos => 'Benzo';

  @override
  String get methPageTitle => 'Pemulihan Sabu';

  @override
  String get methHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get methHeaderNotStarted => 'Jatuhkan Gelasnya';

  @override
  String get methSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get methSubtitleNotStarted => 'Kebebasan ada dalam genggaman Anda';

  @override
  String get methMilestone1Title => '24 Jam Pertama — Fase Crash Dimulai';

  @override
  String get methMilestone1Description =>
      'Fase crash awal dimulai dengan kelelahan berat dan nafsu makan meningkat saat tubuh mulai pulih. Anda mungkin merasa depresi dan tidur jauh lebih banyak ketika tubuh mulai menstabilkan diri setelah stimulasi yang intens.';

  @override
  String get methMilestone3Title => 'Hari ke-3 — Puncak Putus Zat';

  @override
  String get methMilestone3Description =>
      'Keinginan untuk memakai meningkat kuat selama fase ini saat tubuh menyesuaikan diri. Energi dapat mulai naik dibanding fase crash, sehingga dorongan untuk memakai terasa lebih kuat. Ini masa penting untuk pencegahan kekambuhan dan dukungan.';

  @override
  String get methMilestone7Title => 'Satu Minggu — Gejala Fisik Mereda';

  @override
  String get methMilestone7Description =>
      'Gejala putus zat akut mulai mereda, meski tantangan psikologis masih ada. Pola tidur mulai kembali normal dan ketidaknyamanan fisik berkurang. Ini menandai peralihan dari fase putus zat akut ke fase pasca-akut.';

  @override
  String get methMilestone30Title => 'Satu Bulan — Mulai Stabil';

  @override
  String get methMilestone30Description =>
      'Tubuh terus pulih dan keinginan untuk memakai mulai berkurang. Energi meningkat dan suasana hati membaik seiring kimia otak mulai menyeimbangkan diri kembali. Tetap waspada karena tantangan masih bisa muncul.';

  @override
  String get methMilestone90Title => 'Tiga Bulan — Otak Mulai Pulih';

  @override
  String get methMilestone90Description =>
      'Otak Anda sedang aktif pulih. Perhatian, ingatan, dan pengambilan keputusan mulai membaik seiring sistem penghargaan bergerak menuju kondisi yang lebih normal.';

  @override
  String get methMilestone180Title => 'Enam Bulan — Pemulihan Jantung';

  @override
  String get methMilestone180Description =>
      'Fungsi jantung dapat menunjukkan perbaikan terukur setelah berhenti memakai metamfetamin. Studi menunjukkan fungsi jantung dapat membaik secara bermakna selama masa ini, terutama dengan dukungan medis. Tekanan darah dan irama jantung terus menjadi lebih stabil.';

  @override
  String get methMilestone365Title => 'Satu Tahun — Pemulihan Otak Besar';

  @override
  String get methMilestone365Description =>
      'Setelah satu tahun, sistem dopamin telah mengalami banyak pemulihan. Aktivitas sehari-hari kembali terasa lebih memuaskan, sementara suasana hati, ingatan, dan pengambilan keputusan jauh lebih baik.';

  @override
  String get methMilestone420Title => '14 Bulan — Sistem Dopamin Pulih';

  @override
  String get methMilestone420Description =>
      'Pemindaian otak menunjukkan protein yang mendaur ulang dopamin mendekati kadar pada orang sehat di sekitar tahap ini. Ingatan, motivasi, dan kemampuan menikmati kegiatan sehari-hari terus membaik.';

  @override
  String get methMilestone730Title => 'Dua Tahun — Pemulihan Berlanjut';

  @override
  String get methMilestone730Description =>
      'Dua tahun tanpa metamfetamin memberi otak waktu panjang untuk terus pulih. Perhatian, suasana hati, ingatan, dan kualitas hidup sehari-hari dapat terus membaik.';

  @override
  String get addictionNitrousOxide => 'Nitrous Oksida';

  @override
  String get nitrousOxidePageTitle => 'Nitrous Oksida';

  @override
  String get nitrousOxideHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get nitrousOxideHeaderNotStarted => 'Siap Memulai?';

  @override
  String get nitrousOxideSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get nitrousOxideSubtitleNotStarted =>
      'Lihat perubahan positif apa yang menanti Anda';

  @override
  String get nitrousOxideMilestone1Title => '24 Jam Pertama – Gas Keluar';

  @override
  String get nitrousOxideMilestone1Description =>
      'Gas meninggalkan sistem Anda dalam beberapa menit, namun penyembuhan membutuhkan waktu lebih lama. Pusing mereda, sakit kepala mereda, dan otak Anda mulai menyesuaikan diri tanpa jalur pintas dopamin. Pemulihan B12 Anda dimulai sekarang.';

  @override
  String get nitrousOxideMilestone3Title => 'Hari 3 – Tanpa Putus Zat Fisik';

  @override
  String get nitrousOxideMilestone3Description =>
      'Kabar baiknya: dinitrogen oksida tidak menyebabkan putus zat fisik. Dorongan yang Anda rasakan bersifat psikologis – kebiasaan dan asosiasi, bukan tubuh yang menuntut zat tersebut. Karena itu dorongan ini dapat dikelola.';

  @override
  String get nitrousOxideMilestone7Title => 'Satu Minggu – B12 Mulai Naik';

  @override
  String get nitrousOxideMilestone7Description =>
      'Satu minggu tanpa ada B12 baru yang dimusnahkan. Jika Anda sudah mulai mengonsumsi suplemen, level Anda sudah meningkat. Energi, suasana hati, dan fokus semuanya terkait dengan B12 — Anda akan mulai merasakannya meningkat.';

  @override
  String get nitrousOxideMilestone14Title => 'Dua Minggu – Saraf Memulih';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 sangat penting untuk lapisan pelindung pada serabut saraf Anda. Dua minggu kemudian, proses perbaikan tersebut sedang berlangsung secara aktif. Kesemutan atau mati rasa apa pun yang Anda alami seharusnya sudah mereda - sistem saraf Anda sedang memulihkan diri.';

  @override
  String get nitrousOxideMilestone30Title => 'Satu Bulan – Energi Kembali';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12 memainkan peran penting dalam produksi sel darah merah, yang berarti pengiriman oksigen ke setiap sel di tubuh Anda. Pemulihan dan suplementasi selama satu bulan berarti energi yang jauh lebih baik, pemikiran yang lebih jernih, dan suasana hati yang lebih stabil.';

  @override
  String get nitrousOxideMilestone90Title =>
      'Tiga Bulan - Pemulihan Neurologis';

  @override
  String get nitrousOxideMilestone90Description =>
      'Tiga bulan tanpa kerusakan B12 berarti tiga bulan perbaikan saraf. Sistem sarafnya tangguh — kebanyakan orang yang memulai pengobatan segera merasakan pemulihan yang signifikan pada rasa kesemutan, kelemahan, dan kabut otak pada saat ini.';

  @override
  String get nitrousOxideMilestone365Title =>
      'Satu Tahun – Perlindungan Berlanjut';

  @override
  String get nitrousOxideMilestone365Description =>
      'Setahun penuh bebas dari dinitrogen oksida. Simpanan B12 Anda dipulihkan, sistem saraf Anda memiliki waktu satu tahun untuk pulih, dan risiko kardiovaskular akibat peningkatan homosistein telah teratasi. Tubuh Anda kembali menjalankan kimianya sendiri.';

  @override
  String get addictionCocaine => 'Kokain';

  @override
  String get addictionAdderall => 'Tambahan';

  @override
  String get cocainePageTitle => 'Pemulihan Kokain';

  @override
  String get cocaineHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get cocaineHeaderNotStarted => 'Siap Memulai?';

  @override
  String get cocaineSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get cocaineSubtitleNotStarted =>
      'Lihat perubahan positif apa yang menanti Anda';

  @override
  String get cocaineMilestone1Title => '24 Jam Pertama: Awal Perjalanan';

  @override
  String get cocaineMilestone1Description =>
      'Tubuh Anda mulai menyesuaikan diri saat kadar dopamin mulai stabil. Anda mungkin mengalami kelelahan, perubahan suasana hati, dan keinginan kuat untuk menggunakan kokain, tetapi sistem kardiovaskular Anda sudah mulai pulih.';

  @override
  String get cocaineMilestone3Title => 'Hari ke-3: Tantangan Terberat';

  @override
  String get cocaineMilestone3Description =>
      'Gejala putus zat sering memuncak sekitar waktu ini. Keinginan kuat untuk menggunakan, mudah tersinggung, cemas, dan kelelahan dapat muncul. Ini bersifat sementara; otak Anda sedang bekerja untuk menyeimbangkan diri kembali.';

  @override
  String get cocaineMilestone7Title => 'Satu Minggu: Pemulihan Fisik';

  @override
  String get cocaineMilestone7Description =>
      'Gejala fisik yang paling berat mulai mereda. Detak jantung dan tekanan darah mulai stabil. Keinginan psikologis mungkin masih muncul, sementara tubuh Anda terus pulih.';

  @override
  String get cocaineMilestone14Title => 'Dua Minggu: Mulai Stabil';

  @override
  String get cocaineMilestone14Description =>
      'Banyak orang mulai merasa lebih stabil secara emosional. Tingkat energi membaik dan gejala putus zat akut mulai mereda. Kesehatan kardiovaskular juga terus membaik.';

  @override
  String get cocaineMilestone60Title => 'Dua Bulan: Tidur dan Suasana Hati';

  @override
  String get cocaineMilestone60Description =>
      'Kualitas tidur terasa lebih baik saat kimia otak terus menuju kondisi normal. Anda mungkin merasa lebih segar dan mengalami suasana hati yang lebih stabil sepanjang hari.';

  @override
  String get cocaineMilestone90Title => 'Tiga Bulan: Pemulihan Otak';

  @override
  String get cocaineMilestone90Description =>
      'Sistem dopamin Anda sedang pulih. Fokus, pengambilan keputusan, dan pengaturan emosi membaik secara nyata, dan pikiran menjadi lebih jernih.';

  @override
  String get cocaineMilestone180Title => 'Enam Bulan: Pikiran Lebih Jernih';

  @override
  String get cocaineMilestone180Description =>
      'Pemindaian otak menunjukkan pemulihan di bagian depan otak, area yang mendukung perencanaan dan pengendalian diri. Memori, kendali impuls, dan kejernihan berpikir terus menguat.';

  @override
  String get cocaineMilestone365Title => 'Satu Tahun: Kesehatan Jantung';

  @override
  String get cocaineMilestone365Description =>
      'Jantung dan sistem kardiovaskular Anda telah mengalami pemulihan yang berarti. Tekanan darah dan detak jantung telah kembali normal. Risiko serangan jantung dan stroke telah turun secara signifikan. Tubuh Anda terus pulih.';

  @override
  String get cocaineMilestone730Title => 'Dua Tahun - Pemulihan Berkelanjutan';

  @override
  String get cocaineMilestone730Description =>
      'Penyembuhan otak berlanjut dengan peningkatan berkelanjutan dalam memori, fokus, dan regulasi emosional. Jalur saraf Anda telah ditata ulang secara signifikan, mendukung pola yang lebih sehat dan kesejahteraan yang lebih baik secara keseluruhan.';

  @override
  String get cocaineMilestone1095Title => 'Tiga Tahun: Fondasi Kuat';

  @override
  String get cocaineMilestone1095Description =>
      'Tiga tahun bebas kokain adalah kemajuan yang bertahan. Rutinitas, hubungan, dan keterampilan menghadapi masalah yang kamu bangun telah menguat selama bertahun-tahun dan menjadi fondasi pemulihan.';

  @override
  String get cocaineMilestone1460Title => 'Empat Tahun: Momentum Bertahan';

  @override
  String get cocaineMilestone1460Description =>
      'Empat tahun menunjukkan momentum yang bertahan. Satu tahun lagi menjalani hidup tanpa kokain telah memperkuat kebiasaan dan dukungan yang menjaga pemulihan tetap kokoh.';

  @override
  String get cocaineMilestone1825Title => 'Lima Tahun: Perubahan Mengakar';

  @override
  String get cocaineMilestone1825Description =>
      'Lima tahun adalah peringatan besar. Setengah dekade konsistensi telah membangun hidup yang semakin dibentuk oleh nilai, hubungan, dan tujuanmu, bukan oleh kokain.';

