  @override
  String get alcoholMilestone1Title => 'Kualitas Tidur Mulai Membaik';

  @override
  String get alcoholMilestone1Description =>
      'Siklus tidur REM Anda mulai normal pada hari pertama. Meskipun alkohol mungkin membantu Anda tertidur pada awalnya, alkohol mengganggu siklus tidur nyenyak dan REM sepanjang malam, sehingga menyebabkan tidur terfragmentasi.';

  @override
  String get alcoholMilestone3Title =>
      'Hari 3: Putus Alkohol Akut Mencapai Puncak';

  @override
  String get alcoholMilestone3Description =>
      'Tiga hari adalah pencapaian besar: gejala putus alkohol sering memuncak sekitar 72 jam. Tremor, insomnia, agitasi, berkeringat, denyut jantung cepat, dan tekanan darah tinggi dapat terasa paling kuat saat ini. Putus alkohol berat masih dapat muncul kemudian, termasuk delirium pada 3–8 hari setelah berhenti.';

  @override
  String get alcoholMilestone7Title => 'Sistem Kekebalan Tubuh Menguat';

  @override
  String get alcoholMilestone7Description =>
      'Sel darah putih Anda memulihkan fungsinya. Bahkan meminum minuman beralkohol dalam jumlah banyak pun dapat mengganggu fungsi kekebalan tubuh hingga 24 jam, dan konsumsi minuman beralkohol secara terus-menerus secara signifikan melemahkan kemampuan tubuh Anda untuk melawan infeksi.';

  @override
  String get alcoholMilestone14Title => 'Pemulihan Volume Otak Dimulai';

  @override
  String get alcoholMilestone14Description =>
      'Volume otak mulai pulih dalam dua minggu pertama. Pemikiran dan ingatan terus meningkat selama beberapa bulan berikutnya.';

  @override
  String get alcoholMilestone30Title => 'Tekanan Darah Menjadi Normal';

  @override
  String get alcoholMilestone30Description =>
      'Sistem kardiovaskular Anda menunjukkan peningkatan yang signifikan. Konsumsi alkohol secara teratur meningkatkan tekanan darah, namun berpantang selama sekitar satu bulan dapat membantu mengembalikan tekanan darah ke tingkat yang lebih sehat.';

  @override
  String get alcoholMilestone60Title => 'Fungsi Hati Meningkat';

  @override
  String get alcoholMilestone60Description =>
      'Hati Anda menunjukkan peningkatan fungsi yang terukur. Organ regeneratif ini dapat pulih secara signifikan dari kerusakan akibat alkohol, dengan enzim hati dan akumulasi lemak menunjukkan perbaikan dalam waktu 2 bulan setelah berhenti mengonsumsi alkohol.';

  @override
  String get alcoholMilestone90Title => 'Pikiran dan Ingatan Makin Tajam';

  @override
  String get alcoholMilestone90Description =>
      'Tiga bulan pertama membawa peningkatan besar dalam memori, konsentrasi, dan pengambilan keputusan, dengan pemulihan terus berlanjut pada bulan-bulan berikutnya.';

  @override
  String get alcoholMilestone180Title =>
      'Volume dan Fungsi Otak Melanjutkan Pemulihan';

  @override
  String get alcoholMilestone180Description =>
      'Enam bulan sadar memberi otak waktu yang lama untuk pulih. Volume otak dan kemampuan berpikir terus meningkat.';

  @override
  String get alcoholMilestone365Title =>
      'Pengurangan Resiko Kanker Mungkin Dimulai';

  @override
  String get alcoholMilestone365Description =>
      'Pantang selama satu tahun mungkin mulai mengurangi risiko kanker. Meskipun alkohol jelas meningkatkan risiko beberapa jenis kanker (hati, payudara, kolorektal, esofagus), penelitian mengenai jangka waktu pengurangan risiko masih terus bermunculan dan bervariasi berdasarkan jenis kanker.';

  @override
  String get smokingMilestone1Title => 'Karbon Monoksida Menurun';

  @override
  String get smokingMilestone1Description =>
      'Darah Anda kembali membawa lebih banyak oksigen! Dalam 24 jam, kadar karbon monoksida turun ke tingkat normal dan kadar oksigen meningkat. Jantung tidak lagi harus bekerja ekstra untuk memompa darah yang terpapar karbon monoksida ke seluruh tubuh.';

  @override
  String get smokingMilestone3Title => 'Puncak Putus Nikotin';

  @override
  String get smokingMilestone3Description =>
      'Gejala putus nikotin sedang paling kuat, tetapi Anda berhasil melewatinya! Semua nikotin sudah keluar dari tubuh. Keinginan merokok bisa terasa paling berat sekarang, namun setiap gelombang yang terlewati membawa Anda lebih dekat pada kebebasan.';

  @override
  String get smokingMilestone7Title => 'Rasa & Penciuman Membaik';

  @override
  String get smokingMilestone7Description =>
      'Makanan mulai terasa menarik lagi! Merokok merusak indra perasa dan reseptor penciuman. Setelah satu minggu, Anda mulai menemukan kembali rasa yang sempat terlupakan. Saatnya menikmati makanan lagi!';

  @override
  String get smokingMilestone14Title => 'Sirkulasi & Jalan Membaik';

  @override
  String get smokingMilestone14Description =>
      'Kakimu berterima kasih pada setiap langkahmu! Sirkulasi darah meningkat secara dramatis, membuat berjalan dan berolahraga menjadi lebih mudah. Tangga itu tidak terlihat menakutkan lagi, bukan?';

  @override
  String get smokingMilestone30Title => 'Fungsi Paru-paru Meningkat';

  @override
  String get smokingMilestone30Description =>
      'Paru-paru Anda sedang bangkit! Silia tumbuh kembali dan membantu membersihkan lendir, tar, serta kotoran yang menumpuk. Fungsi paru membaik, dan batuk khas perokok mulai mereda.';

  @override
  String get smokingMilestone90Title => 'Risiko Serangan Jantung Turun';

  @override
  String get smokingMilestone90Description =>
      'Hatimu mengirimkan surat cinta! Tiga bulan bebas rokok dan risiko kardiovaskular Anda telah menurun secara signifikan. Sistem kardiovaskular Anda pulih lebih cepat dari yang Anda bayangkan.';

  @override
  String get smokingMilestone180Title => 'Sel Imun Paru Mulai Bangkit';

  @override
  String get smokingMilestone180Description =>
      'Enam bulan bebas rokok adalah kemenangan nyata bagi pertahanan paru. Dalam studi bedah, respons makrofag alveolar melawan bakteri setelah 3–12 bulan bebas rokok lebih mendekati pola orang yang tidak pernah merokok dibanding pada dua bulan. Sel pertahanan terdepan paru Anda sudah punya berbulan-bulan untuk pulih.';

  @override
  String get smokingMilestone365Title => 'Risiko Stroke Turun';

  @override
  String get smokingMilestone365Description =>
      'Satu tahun penuh kebebasan! Risiko stroke Anda telah menurun secara signifikan, dan pembuluh darah Anda pulih dengan baik. Anda secara resmi telah memberikan otak Anda hadiah sirkulasi dan perlindungan yang lebih baik.';

  @override
  String get smokingMilestone730Title => 'Dua Tahun: Jantung Lebih Kuat';

  @override
  String get smokingMilestone730Description =>
      'Dua tahun bebas rokok adalah pencapaian besar bagi jantung dan pembuluh darah. CDC menyatakan risiko serangan jantung turun tajam dalam 1–2 tahun setelah berhenti, sedangkan risiko penyakit jantung koroner terus menurun dalam jangka panjang.';

  @override
  String get smokingMilestone1095Title => 'Tiga Tahun: Risiko Jantung Turun';

  @override
  String get smokingMilestone1095Description =>
      'Tiga tahun bebas rokok menandai awal rentang 3–6 tahun CDC, ketika risiko tambahan penyakit jantung koroner berkurang setengah. Penurunan berlangsung sepanjang rentang itu, bukan pada satu hari tertentu.';

  @override
  String get smokingMilestone1460Title => 'Empat Tahun: Manfaat Jantung Naik';

  @override
  String get smokingMilestone1460Description =>
      'Empat tahun bebas rokok berada di dalam rentang 3–6 tahun CDC, ketika risiko tambahan penyakit jantung koroner berkurang setengah. Manfaat kardiovaskular jangka panjang terus bertambah.';

  @override
  String get smokingMilestone1825Title => '5–10 Tahun: Risiko Kanker Turun';

  @override
  String get smokingMilestone1825Description =>
      'Lima tahun kemenangan! Anda memasuki jendela 5–10 tahun ketika risiko tambahan kanker mulut, tenggorokan, dan laring turun setengah, sementara risiko stroke terus menurun. Manfaat jangka panjang kini benar-benar mulai terasa.';

  @override
  String get marijuanaMilestone1Title => 'Gejala Putus Zat Dimulai';

  @override
  String get marijuanaMilestone1Description =>
      'Otak Anda sedang menyesuaikan diri dengan hidup tanpa THC. Dalam 24–48 jam, Anda mungkin merasa mudah tersinggung, cemas, atau sulit tidur. Ini wajar: reseptor kanabinoid mulai menyesuaikan diri kembali.';

  @override
  String get marijuanaMilestone3Title => 'Puncak Gejala Fisik';

  @override
  String get marijuanaMilestone3Description =>
      'Anda sedang melewati bagian yang paling berat, tetapi arahnya membaik dari sini. Hari ke-2 hingga ke-6 biasanya menjadi puncak gejala putus zat seperti sakit kepala, berkeringat, dan perubahan suasana hati. Tubuh Anda sedang bekerja keras untuk kembali seimbang.';

  @override
  String get marijuanaMilestone7Title => 'Pola Tidur Membaik';

  @override
  String get marijuanaMilestone7Description =>
      'Mimpi mulai kembali. Setelah seminggu tanpa kanabis, pola tidur alami Anda mulai menormal. Tidur REM memantul kembali, sehingga mimpi bisa lebih jelas dan kualitas istirahat membaik.';

  @override
  String get marijuanaMilestone14Title => 'Putus Zat Akut Berakhir';

  @override
  String get marijuanaMilestone14Description =>
      'Badai mulai berlalu. Sebagian besar gejala fisik putus zat berkurang nyata setelah dua minggu. Suasana hati mulai lebih stabil dan aktivitas sehari-hari terasa lebih mudah. Bagian terberat sudah di belakang Anda.';

  @override
  String get marijuanaMilestone30Title => 'Fungsi Memori Membaik';

  @override
  String get marijuanaMilestone30Description =>
      'Kabut otak mulai terangkat. Penelitian menunjukkan pembelajaran verbal dan memori mulai membaik setelah penggunaan kanabis dihentikan. Hipokampus, yang penting untuk pembentukan memori, mulai berfungsi lebih baik.';

  @override
  String get marijuanaMilestone60Title => 'Konsentrasi Meningkat';

  @override
  String get marijuanaMilestone60Description =>
      'Mode fokus mulai kembali. Dua bulan tanpa kanabis dan kemampuan Anda untuk berkonsentrasi serta mempertahankan perhatian menunjukkan peningkatan nyata. Tugas kerja dan belajar menjadi lebih mudah dikelola.';

  @override
  String get marijuanaMilestone90Title => 'Suasana Hati Lebih Stabil';

  @override
  String get marijuanaMilestone90Description =>
      'Tiga bulan tanpa kanabis dapat membawa suasana hati yang lebih stabil, lebih sedikit kecemasan, dan pengelolaan stres yang lebih baik. Keadaan emosi Anda mulai menetap ke pola yang lebih sehat.';

  @override
  String get marijuanaMilestone180Title => 'Perencanaan dan Keputusan Pulih';

  @override
  String get marijuanaMilestone180Description =>
      'Kemampuan mengatur diri kembali memegang kendali. Enam bulan tanpa kanabis membawa kemajuan besar dalam perencanaan, pengambilan keputusan, dan pemecahan masalah.';

  @override
  String get marijuanaMilestone365Title => 'Pemulihan Struktur Otak';

  @override
  String get marijuanaMilestone365Description =>
      'Satu tahun tanpa kanabis memberi area otak yang berkaitan dengan memori waktu yang panjang untuk pulih. Perbaikan belajar dan memori kini menjadi bagian dari keseharian baru Anda.';

  @override
  String get opioidMilestone1Title => 'Penarikan Akut Dimulai';

  @override
  String get opioidMilestone1Description =>
      'Bagian tersulit dimulai sekarang, tapi Anda tidak sendirian. Gejala putus obat akut mencapai puncaknya dalam 24-72 jam pertama. Ini adalah tubuh Anda yang memulai proses penyembuhan. Dukungan medis profesional sangat penting selama fase ini.';

  @override
  String get opioidMilestone7Title => 'Gejala Fisik Memuncak & Mulai Menurun';

  @override
  String get opioidMilestone7Description =>
      'Anda berhasil melewati badai! Gejala penarikan fisik terburuk biasanya mencapai puncaknya sekitar hari ke 3-5 dan mulai menurun pada hari ke 7. Tubuh Anda bekerja keras untuk memulihkan keseimbangan alaminya.';

  @override
  String get opioidMilestone14Title => 'Pola Tidur Mulai Membaik';

  @override
  String get opioidMilestone14Description =>
      'Mimpi indah kembali lagi! Dua minggu kemudian, arsitektur tidur alami Anda mulai pulih. Opioid mengganggu tidur REM, tetapi otak Anda belajar untuk bermimpi lagi secara alami.';

  @override
  String get opioidMilestone30Title => 'Pemikiran dan Ingatan Mulai Pulih';

  @override
  String get opioidMilestone30Description =>
      'Kabut otak mulai terangkat! Satu bulan bersih dan ingatan, pengambilan keputusan, dan pemikiran jernih meningkat seiring pemulihan bagian depan otak dari perubahan terkait opioid.';

  @override
  String get opioidMilestone60Title => 'Regulasi Emosional Meningkat';

  @override
  String get opioidMilestone60Description =>
      'Emosi Anda menemukan ritme alaminya kembali. Dua bulan dalam pemulihan dan sistem penghargaan otak Anda mulai merespons kesenangan sehari-hari. Rollercoaster emosional mulai stabil.';

  @override
  String get opioidMilestone90Title => 'Fungsi Dopamin Pulih Secara Signifikan';

  @override
  String get opioidMilestone90Description =>
      'Sistem penghargaan otak Anda mengadakan pesta selamat datang kembali! Fungsi bersih dan dopamin selama tiga bulan telah meningkat secara signifikan. Aktivitas alami mulai terasa bermanfaat lagi - makanan, musik, hubungan.';

  @override
  String get opioidMilestone180Title => 'Sistem Kekebalan Tubuh Menguat';

  @override
  String get opioidMilestone180Description =>
      'Sistem kekebalan Anda kembali bertugas patroli! Enam bulan pemulihan dan pertahanan alami tubuh Anda telah diperkuat secara signifikan. Anda lebih siap untuk melawan infeksi dan penyakit.';

  @override
  String get opioidMilestone365Title =>
      'Plastisitas Syaraf & Struktur Otak Meningkat';

  @override
  String get opioidMilestone365Description =>
      'Otak Anda sedang sibuk merenovasi! Pemulihan satu tahun penuh menunjukkan perbaikan signifikan pada struktur otak dan plastisitas saraf. Perubahan akibat penggunaan opioid kronis mengalami penyembuhan yang sangat baik.';

  @override
  String get opioidMilestone730Title =>
      'Stabilitas Pemulihan Jangka Panjang (2 Tahun)';

  @override
  String get opioidMilestone730Description =>
      'Dua tahun kekuatan dan ketahanan! Anda telah membangun jalur saraf baru, strategi penanggulangan, dan pola hidup. Penelitian menunjukkan bahwa mencapai tahap ini secara dramatis mengurangi risiko kambuh. Anda adalah pejuang pemulihan!';

  @override
  String get opioidMilestone1095Title => 'Tiga Tahun - Tetap Pulih';

  @override
  String get opioidMilestone1095Description =>
      'Tiga tahun pemulihan berkelanjutan. Rutinitas, dukungan, perawatan, dan pilihan harian yang membawa Anda sampai di sini layak dirayakan.';

  @override
  String get opioidMilestone1460Title => 'Empat Tahun - Fondasi Kuat';

  @override
  String get opioidMilestone1460Description =>
      'Empat tahun perubahan yang konsisten telah menjadikan pemulihan bagian yang kokoh dari hidup Anda. Fondasi ini layak diapresiasi.';

  @override
  String get opioidMilestone1825Title => 'Lima Tahun - Setengah Dekade';

  @override
  String get opioidMilestone1825Description =>
      'Lima tahun adalah setengah dekade perubahan berkelanjutan. Itu adalah pencapaian besar dengan sendirinya.';

  @override
  String get socialMediaMilestone1Title => 'Detoks Digital Hari Pertama! 🎯';

  @override
  String get socialMediaMilestone1Description =>
      'Anda resmi memulai perubahan kebiasaan digital. Dorongan untuk mengecek media sosial mungkin masih kuat, tetapi setiap kali Anda memilih untuk tidak membuka feed, Anda sedang memutus pola lama.';

  @override
  String get socialMediaMilestone3Title => 'FOMO? Lebih Seperti FO-NO! 😎';

  @override
  String get socialMediaMilestone3Description =>
      'Tiga hari berlalu, dan pikiran cemas seperti ‘apa yang saya lewatkan?’ mulai mereda. Anda sedang melatih diri bahwa kehidupan nyata lebih menarik daripada feed yang dikurasi.';

  @override
  String get socialMediaMilestone7Title => 'Fokus Kembali ke Manusia 🧠';

  @override
  String get socialMediaMilestone7Description =>
      'Satu minggu selesai! Fokus tanpa mengecek ponsel setiap beberapa menit mulai terasa lebih mudah. Anda sedang membangun kebiasaan mencari kepuasan di luar notifikasi.';

  @override
  String get socialMediaMilestone14Title => 'Tidur Lebih Nyenyak 😴';

  @override
  String get socialMediaMilestone14Description =>
      'Dua minggu tanpa kebiasaan scrolling sebelum tidur berarti lebih banyak ruang untuk rutinitas malam yang tenang dan kualitas tidur yang lebih baik.';

  @override
  String get socialMediaMilestone30Title => 'Teman Sejati > Suka Palsu 💝';

  @override
  String get socialMediaMilestone30Description =>
      'Satu bulan dengan media sosial jauh lebih sedikit. Waktu dan perhatian yang dulu tersedot feed sekarang bisa kembali ke hubungan nyata dan aktivitas yang benar-benar Anda pilih.';

  @override
  String get socialMediaMilestone60Title => 'Lolos dari Jebakan Banding ✨';

  @override
  String get socialMediaMilestone60Description =>
      'Dua bulan tanpa perbandingan sosial yang terus-menerus memberi ruang bagi rasa percaya diri yang lebih stabil. Anda tidak lagi harus menilai hidup sendiri lewat unggahan orang lain.';

  @override
  String get socialMediaMilestone90Title => 'Waktu untuk Hobi 🎨';

  @override
  String get socialMediaMilestone90Description =>
      'Tiga bulan berarti banyak waktu yang kembali ke tangan Anda. Rutinitas offline yang terus diulang kini makin mudah dan lebih otomatis.';

  @override
  String get socialMediaMilestone180Title => 'Enam Bulan Lebih Terkendali 🌟';

  @override
  String get socialMediaMilestone180Description =>
      'Enam bulan mempertahankan batas digital adalah pencapaian besar. Anda sudah membuktikan bahwa perhatian tidak harus dikendalikan oleh feed.';

  @override
  String get socialMediaMilestone365Title => 'Setahun Hidup Lebih Sengaja 🏆';

  @override
  String get socialMediaMilestone365Description =>
      'Satu tahun penuh membuat keputusan digital dengan sengaja. Kebiasaan mengecek otomatis sudah punya waktu lama untuk melemah, sementara hubungan dan rutinitas offline punya waktu untuk tumbuh.';

  @override
  String get nicotinePouchesMilestone1Title =>
      'Gejala Putus Nikotin Sudah Dimulai';

  @override
  String get nicotinePouchesMilestone1Description =>
      'Putus nikotin dapat mulai 4–24 jam setelah kantong terakhir Anda. Hari pertama tanpa kantong adalah tonggak biologis nyata — tubuh Anda sudah beradaptasi dengan hidup tanpa asupan nikotin berulang.';

  @override
  String get nicotinePouchesMilestone3Title => 'Putus Nikotin Mencapai Puncak';

  @override
  String get nicotinePouchesMilestone3Description =>
      'Putus nikotin biasanya mencapai puncak sekitar hari ketiga, lalu mereda selama 3–4 minggu berikutnya. Anda sudah berada di puncak bukit — dari sini, tren keseluruhannya menurun.';

  @override
  String get nicotinePouchesReferenceDay1 =>
      'Hari Pertama: Putus Nikotin Dimulai\n\nSumber: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nTinjauan tentang penghentian penggunaan kronis produk yang mengandung nikotin melaporkan bahwa sindrom putus nikotin dapat dimulai 4–24 jam setelah berhenti. Itu membuat hari pertama tanpa kantong menjadi tonggak fisiologis yang nyata.\n\nApa selanjutnya\nGejala biasanya mencapai puncak sekitar hari ke-3 lalu mereda selama 3–4 minggu berikutnya. Intensitas putus nikotin berbeda menurut cara nikotin dikonsumsi, sehingga pengalaman tiap orang dapat berbeda.';

  @override
  String get nicotinePouchesReferenceDay3 =>
      'Hari Ketiga: Puncak Putus Nikotin\n\nSumber: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nTinjauan ini menempatkan puncak khas putus nikotin sekitar hari ketiga setelah menghentikan penggunaan nikotin kronis.\n\nKurva setelah ini\nSetelah puncak, gejala biasanya mereda selama 3–4 minggu berikutnya. Tinjauan ini juga mencatat bahwa tingkat keparahan dipengaruhi oleh cara nikotin dikonsumsi, jadi intensitas tepatnya berbeda pada tiap orang.\n\nHari ketiga adalah tonggak yang diperjuangkan: Anda sudah mencapai puncak kurva awal putus nikotin yang khas.';

  @override
  String get nicotinePouchesMilestone7Title =>
      'Satu Minggu: Gejala Putus Nikotin Mereda';

  @override
  String get nicotinePouchesMilestone7Description =>
      'Satu minggu tanpa kantong nikotin menempatkanmu melewati puncak gejala putus nikotin yang biasanya terjadi sekitar hari ketiga. Gejala umumnya mereda selama 3–4 minggu berikutnya — kamu sudah berada di sisi menurun.';

  @override
  String get nicotinePouchesMilestone14Title =>
      'Dua Minggu: Gejala Terus Mereda';

  @override
  String get nicotinePouchesMilestone14Description =>
      'Dua minggu tanpa kantong nikotin menempatkanmu jauh di dalam fase penurunan 3–4 minggu yang biasanya mengikuti puncak hari ketiga. Kurvanya masih turun — pemulihan nyata sedang berjalan.';

  @override
  String get nicotinePouchesReferenceDay7 =>
      'Satu Minggu: Gejala Putus Nikotin Mereda\n\nSumber: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nTinjauan tersebut melaporkan bahwa gejala putus setelah penggunaan kronis produk yang mengandung nikotin mulai 4–24 jam setelah berhenti, mencapai puncak sekitar hari ke-3, lalu mereda selama 3–4 minggu berikutnya.\n\nKemenangan nyata satu minggu\nPada satu minggu, kamu sudah beberapa hari melewati puncak yang umum dan masuk ke fase penurunan. Tinjauan itu juga mencatat bahwa tingkat keparahan putus nikotin berbeda menurut cara nikotin dikonsumsi, sehingga intensitasnya berbeda antarorang.\n\nSatu minggu tanpa kantong nikotin berarti bagian paling curam dari kurva putus nikotin awal yang umum sudah berada di belakangmu.';

  @override
  String get nicotinePouchesReferenceDay14 =>
      'Dua Minggu: Gejala Terus Mereda\n\nSumber: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nTinjauan tersebut menempatkan puncak umum putus nikotin sekitar hari ke-3 dan menyatakan bahwa gejala mereda selama 3–4 minggu berikutnya.\n\nJauh masuk fase penurunan\nPada dua minggu, kamu sudah jauh masuk ke jendela penurunan setelah puncak. Tinjauan ini membahas penggunaan kronis produk yang mengandung nikotin dan mencatat bahwa keparahan putus nikotin berbeda menurut cara nikotin dikonsumsi.\n\nDua minggu tanpa kantong nikotin adalah titik nyata pada kurva menurun: sindrom putus nikotin yang umum terus mereda.';

  @override
  String get nicotinePouchesMilestone730Title =>
      'Dua Tahun: Kuat Tanpa Kantong';

  @override
  String get nicotinePouchesMilestone730Description =>
      'Dua tahun penuh tanpa kantong nikotin. Riset belum menetapkan ambang pemulihan khusus pada dua tahun, jadi pencapaian ini merayakan dua tahun tanpa paparan nikotin berulang dari kantong dan perubahan yang berhasil dipertahankan.';

  @override
  String get nicotinePouchesReferenceDay730 =>
      'Dua Tahun: Kuat Tanpa Kantong\n\nSumber: Rungraungrayabkul dkk. (2024), tinjauan sistematis tentang kantong nikotin dan kesehatan mulut\n\nTinjauan ini hanya menemukan tiga studi pada manusia dengan total 190 peserta, dan semuanya dinilai berisiko bias tinggi. Tinjauan tersebut tidak menetapkan ambang pemulihan pada dua tahun setelah berhenti.\n\nDua tahun tanpa kantong tetap merupakan pencapaian besar dari perubahan yang bertahan. Entri ini merayakan keberhasilan itu tanpa mengarang jadwal medis.';

  @override
  String get nicotinePouchesMilestone1095Title =>
      'Tiga Tahun: Kebebasan Bertahan';

  @override
  String get nicotinePouchesMilestone1095Description =>
      'Tiga tahun tanpa kantong adalah kemenangan yang bertahan lama. Efek jangka panjang kantong nikotin masih diteliti, jadi inti yang jujur sederhana: tiga tahun bebas secara konsisten dari nikotin kantong.';

  @override
  String get nicotinePouchesReferenceDay1095 =>
      'Tiga Tahun: Kebebasan Bertahan\n\nSumber: CDC — Kantong Nikotin\n\nCDC menyatakan bahwa riset lebih lanjut diperlukan untuk memahami efek kesehatan jangka pendek dan panjang dari kantong nikotin. CDC tidak menyebut perubahan medis khusus pada tiga tahun setelah berhenti.\n\nTiga tahun tanpa kantong layak dirayakan apa adanya: tiga tahun bebas secara konsisten dari nikotin kantong.';

  @override
  String get nicotinePouchesMilestone1460Title => 'Empat Tahun: Tetap Kokoh';

  @override
  String get nicotinePouchesMilestone1460Description =>
      'Empat tahun tanpa kantong menunjukkan konsistensi nyata. Tidak ada perubahan medis tervalidasi yang terjadi tepat pada empat tahun, tetapi ada pencapaian yang sangat nyata: empat tahun tanpa kembali ke kebiasaan memakai kantong.';

  @override
  String get nicotinePouchesReferenceDay1460 =>
      'Empat Tahun: Tetap Kokoh\n\nSumber: Rungraungrayabkul dkk. (2024), tinjauan sistematis tentang kantong nikotin dan kesehatan mulut\n\nTinjauan menyimpulkan bahwa bukti tentang efek kesehatan mulut jangka pendek dan panjang masih terbatas dan riset lebih lanjut diperlukan. Bukti itu tidak mendukung peristiwa pemulihan universal tepat pada empat tahun.\n\nEmpat tahun tanpa kantong adalah tonggak perubahan yang bertahan tanpa perlu klaim medis yang belum terbukti.';

  @override
  String get nicotinePouchesMilestone1825Title =>
      'Lima Tahun: Kemenangan Besar';

  @override
  String get nicotinePouchesMilestone1825Description =>
      'Lima tahun tanpa kantong adalah pencapaian besar. Riset jangka panjang masih berkembang, jadi tonggak ini tidak membuat janji kesehatan yang dibuat-buat; yang dirayakan adalah lima tahun perubahan yang bertahan.';

  @override
  String get nicotinePouchesReferenceDay1825 =>
      'Lima Tahun: Kemenangan Besar\n\nSumber: CDC — Kantong Nikotin\n\nCDC mencatat bahwa kantong nikotin relatif baru dan efek kesehatan jangka panjangnya masih dipelajari. Bukti saat ini tidak menetapkan peristiwa pemulihan khusus pada lima tahun.\n\nLima tahun tanpa kantong adalah pencapaian besar dengan sendirinya: lima tahun perubahan yang bertahan.';

  @override
  String get pornographyMilestone1Title => 'Mengambil Kembali Kendali';

  @override
  String get pornographyMilestone1Description =>
      'Penggunaan pornografi yang bermasalah ditandai oleh hilangnya kendali yang menimbulkan tekanan atau gangguan fungsi. Hari pertama berarti karena Anda sudah sekali memutus pola lama dan mulai mengenali apa yang memicunya.';

  @override
  String get pornographyMilestone3Title => 'Ketahui Desakan Anda';

  @override
  String get pornographyMilestone3Description =>
      'Orang dengan masalah penggunaan yang lebih parah biasanya melaporkan pikiran seksual yang mengganggu, hasrat yang sulit dikendalikan, mudah tersinggung, perubahan suasana hati, dan masalah tidur. Hari ketiga adalah poin yang berguna untuk menyebutkan hal mana yang benar-benar terjadi pada Anda.';

  @override
  String get pornographyMilestone7Title => 'Satu Minggu: Bukti Uji Acak';

  @override
  String get pornographyMilestone7Description =>
      'Dalam studi pantang secara acak selama 7 hari, pengguna reguler tidak menunjukkan sindrom penarikan secara keseluruhan. Subkelompok eksplorasi dengan penggunaan bermasalah yang tinggi dan tontonan harian memiliki keinginan yang lebih besar, sehingga minggu pertama yang sulit mungkin saja terjadi, tetapi bukannya tidak bisa dihindari.';

  @override
  String get pornographyMilestone14Title => 'Petakan Pemicu Anda';

  @override
  String get pornographyMilestone14Description =>
      'Dua minggu memberi Anda paparan berulang terhadap situasi yang dulunya merupakan isyarat pornografi. Penelitian menghubungkan penggunaan yang bermasalah dengan faktor-faktor termasuk keinginan, stres, penghindaran, kesepian, dan gaya mengatasi; mengetahui pola Anda sendiri memberi Anda sesuatu yang konkret untuk diubah.';

  @override
  String get pornographyMilestone30Title => 'Bulan Kendali';

  @override
  String get pornographyMilestone30Description =>
      'Sebulan adalah ujian kendali yang berarti. Dalam penelitian yang melibatkan 14.581 orang, masalah fungsi seksual dikaitkan lebih kuat dengan penggunaan yang bermasalah dibandingkan dengan frekuensi menonton biasa, sehingga mendapatkan kembali kendali adalah target yang lebih berbasis bukti.';

  @override
  String get pornographyMilestone90Title => 'Perubahan Bisa Bertahan';

  @override
  String get pornographyMilestone90Description =>
      'Uji coba ACT secara acak untuk penggunaan pornografi bermasalah menemukan penurunan besar dalam penayangan setelah 12 sesi, dengan pengurangan substansial masih terjadi pada tindak lanjut 3 bulan. Perubahan yang bertahan lama adalah hal yang realistis, terutama ketika Anda membangun keterampilan terstruktur daripada hanya mengandalkan kemauan keras.';

  @override
  String get pornographyMilestone180Title => 'Stabilitas Enam Bulan';

  @override
  String get pornographyMilestone180Description =>
      'Sebuah studi CBT acak untuk perilaku seksual di luar kendali menemukan perbaikan gejala, kompulsifitas seksual, dan kesejahteraan yang tetap stabil pada masa tindak lanjut 3 dan 6 bulan. Pengendalian jangka panjang dapat dipertahankan.';

  @override
  String get pornographyMilestone365Title => 'Setahun: Perubahan Bertahan';

  @override
  String get pornographyMilestone365Description =>
      'Data tindak lanjut satu tahun dari studi pengobatan berbasis penerimaan menemukan peserta tidak kembali ke tingkat hiperseksualitas sebelum pengobatan. Perubahan yang dipertahankan selama setahun adalah bukti kredibel dari pola yang bertahan lama, bukan tanggal yang ajaib untuk mengatur ulang otak.';

  @override
  String get pornographyMilestone730Title => 'Dua Tahun: Kendali Stabil';

  @override
  String get pornographyMilestone730Description =>
      'Dua tahun perubahan yang terjaga adalah pencapaian perilaku yang besar. Bukti tentang CSBD dan penggunaan pornografi bermasalah berfokus pada kendali, tekanan, fungsi, dan konteks, bukan pada pemulihan otak universal tepat dua tahun. Pertahankan rutinitas yang memudahkan pilihan yang sehat.';

  @override
  String get pornographyMilestone1095Title => 'Tiga Tahun: Makin Kokoh';

  @override
  String get pornographyMilestone1095Description =>
      'Tiga tahun menunjukkan bahwa perubahan telah bertahan melewati berbagai suasana hati, rutinitas, dan peristiwa hidup. Tidak ada garis akhir biologis tiga tahun yang didukung bukti; kendali yang bertahan dan fungsi yang lebih baik sudah merupakan hasil penting.';

  @override
  String get pornographyMilestone1460Title =>
      'Empat Tahun: Perubahan Tahan Lama';

  @override
  String get pornographyMilestone1460Description =>
      'Empat tahun adalah pemeliharaan yang tahan lama. Bukti terbaik melihat CSBD dan penggunaan pornografi bermasalah sebagai masalah yang kompleks dan individual; tetap ukur hal yang penting: kendali, tekanan, hubungan, penggunaan waktu, dan apakah pola lama masih mengganggu kehidupan.';

  @override
  String get pornographyMilestone1825Title => 'Lima Tahun Tetap Terkendali';

  @override
  String get pornographyMilestone1825Description =>
      'Lima tahun menunjukkan perubahan yang terjaga dalam jangka panjang. CSBD secara klinis ditandai oleh hilangnya kendali yang menetap disertai tekanan atau gangguan fungsi, sehingga mempertahankan kendali dan fungsi yang baik selama bertahun-tahun merupakan hasil yang bermakna.';

  @override
  String get customMilestone1Title => '24 Jam Pertama Selesai';

  @override
  String get customMilestone1Description =>
      'Anda telah melewati satu hari penuh tanpa kebiasaan yang Anda pilih untuk dihentikan. Pada hari-hari pertama setelah berhenti dari beberapa zat, putus zat dapat mengganggu tidur, dan perubahan tidur dapat berlanjut selama pemulihan. Memantau tidur dapat membantu Anda lebih mudah melihat perubahan tersebut.';

  @override
  String get customMilestone3Title => 'Puncak Gejala Putus Zat';

  @override
  String get customMilestone3Description =>
      'Anda sedang menghadapi bagian yang berat. Pada banyak zat, gejala fisik putus zat biasanya memuncak sekitar hari ketiga, termasuk kecemasan, perubahan suasana hati, dan rasa tidak nyaman secara fisik. Artinya, Anda sedang melewati fase yang paling sulit.';

  @override
  String get customMilestone7Title => 'Fase Akut Mulai Mereda';

  @override
  String get customMilestone7Description =>
      'Bagian terburuk mulai terlewati. Setelah satu minggu, gejala akut putus zat pada banyak zat mulai mereda. Tubuh Anda sedang menyesuaikan diri dengan kondisi baru dan mulai lebih stabil.';

  @override
  String get customMilestone14Title => 'Stabilisasi Pemulihan Dini';

  @override
  String get customMilestone14Description =>
      'Pikiran mulai lebih jernih. Dua minggu menjalani pemulihan sering membawa kejernihan mental yang lebih baik dan keinginan menggunakan yang berkurang, saat otak mulai beradaptasi untuk berfungsi tanpa zat adiktif.';

  @override
  String get customMilestone30Title => 'Pencapaian Satu Bulan';

  @override
  String get customMilestone30Description =>
      'Kemenangan besar! Tiga puluh hari ketenangan menunjukkan kemajuan yang signifikan. Banyak orang mendapati pola tidur, suasana hati, dan tingkat energi terus membaik selama periode ini.';

  @override
  String get customMilestone90Title => 'Tonggak Pemulihan Tiga Bulan';

  @override
  String get customMilestone90Description =>
      'Komitmen Anda membuahkan hasil. Tiga bulan pemulihan adalah pencapaian besar. Gejala putus zat pasca-akut biasanya mulai memudar, dan banyak orang melaporkan mulai merasa seperti diri mereka sendiri lagi.';

  @override
  String get customMilestone180Title => 'Pencapaian Pemulihan Enam Bulan';

  @override
  String get customMilestone180Description =>
      'Anda sedang membangun perubahan yang langgeng! Ketenangan selama enam bulan sering kali membawa perbaikan berkelanjutan dalam kesehatan fisik, stabilitas emosional, dan kualitas hidup secara keseluruhan seiring proses penyembuhan tubuh Anda.';

  @override
  String get customMilestone365Title => 'Satu Tahun Pemulihan';

  @override
  String get customMilestone365Description =>
      'Sebuah pencapaian yang luar biasa! Satu tahun ketenangan merupakan tonggak penting dalam hidup. Banyak orang mengalami peningkatan signifikan dalam kesehatan fisik, hubungan, dan kesejahteraan secara keseluruhan pada saat ini.';

  @override
  String get customMilestone730Title => 'Dua Tahun Pemulihan Berkelanjutan';

  @override
  String get customMilestone730Description =>
      'Anda telah membangun kehidupan baru! Pemulihan selama dua tahun menunjukkan ketahanan dan komitmen yang luar biasa. Ketenangan jangka panjang sering kali membawa perubahan positif yang besar di semua bidang kehidupan dan secara signifikan mengurangi risiko kambuh.';

  @override
  String get customMilestone1095Title => 'Tiga Tahun: Akar yang Kuat';

  @override
  String get customMilestone1095Description =>
      'Tiga tahun pemulihan adalah kemajuan yang berkelanjutan. Rutinitas, hubungan, dan keterampilan menghadapi tantangan telah bertumbuh selama bertahun-tahun. Teruskan hal-hal yang terbukti membantu.';

  @override
  String get customMilestone1460Title => 'Empat Tahun: Perubahan Bertahan';

  @override
  String get customMilestone1460Description =>
      'Empat tahun membuat perubahan yang bertahan terlihat nyata. Pilihan dan dukungan yang membawa Anda sampai di sini kini menjadi bagian dari keseharian. Jaga semuanya dan terus maju.';

  @override
  String get customMilestone1825Title => 'Lima Tahun: Setengah Dekade';

  @override
  String get customMilestone1825Description =>
      'Lima tahun adalah setengah dekade kemajuan yang berkelanjutan. Rayakan kehidupan, keterampilan, dan jaringan dukungan yang telah Anda bangun, lalu terus rawat rutinitas yang membantu Anda berkembang.';

  @override
  String get customReferenceDay1095 =>
      'Tiga Tahun Pemulihan: Akar yang Kuat\n\nSumber: NIDA, Narkoba, Otak, dan Perilaku: Ilmu tentang Adiksi\n\nNIDA menjelaskan gangguan penggunaan zat sebagai kondisi yang dapat diobati dan pemulihan sebagai berhenti menggunakan narkoba lalu kembali menjalani hidup yang produktif. Tidak ada batas biologis tiga tahun yang berlaku untuk semua zat.\n\nTiga tahun adalah pencapaian yang kokoh. Rutinitas, dukungan, dan pilihan yang membawa Anda ke sini telah bertumbuh selama bertahun-tahun.';

  @override
  String get customReferenceDay1460 =>
      'Empat Tahun Pemulihan: Perubahan Bertahan\n\nSumber: NIDA, Narkoba, Otak, dan Perilaku: Ilmu tentang Adiksi\n\nNIDA memandang adiksi sebagai kondisi yang dapat diobati dan dikelola dengan baik. Tidak ada titik akhir kesehatan empat tahun yang berlaku untuk setiap zat atau setiap orang.\n\nEmpat tahun menunjukkan kekuatan konsistensi. Terus jaga kebiasaan, hubungan, dan dukungan yang membuat pemulihan tetap bertahan.';

  @override
  String get customReferenceDay1825 =>
      'Lima Tahun Pemulihan: Setengah Dekade\n\nSumber: NIDA, Narkoba, Otak, dan Perilaku: Ilmu tentang Adiksi\n\nNIDA mendukung pengobatan dan pemulihan berbasis bukti, tetapi tidak menyatakan bahwa setiap orang mencapai kondisi biologis yang sama setelah lima tahun.\n\nLima tahun adalah setengah dekade kemajuan berkelanjutan. Rayakan apa yang telah Anda bangun dan terus pertahankan hal-hal yang terbukti membantu.';

  @override
  String get addictionSsri => 'SSRI';

  @override
  String get ssriPageTitle => 'Pemulihan SSRI';

  @override
  String get ssriHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get ssriHeaderNotStarted => 'Manfaat Mengurangi SSRI';

  @override
  String get ssriSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get ssriSubtitleNotStarted =>
      'Lihat apa yang terjadi saat Anda melakukan pengurangan bertahap';

  @override
  String get ssriMilestone3Title => 'Hari 3: Puncak Sindrom FINISH';

  @override
  String get ssriMilestone3Description =>
      'Gejala putus obat sering mencapai puncak sekitar hari ke-2 sampai ke-4. SSRI mengubah cara serotonin digunakan kembali, sehingga otak memerlukan waktu untuk menyesuaikan diri setelah obat dihentikan. Gejala dapat berupa rasa seperti flu, pusing, sulit tidur, mual, dan sensasi seperti sengatan listrik di kepala (“brain zaps”). Paroxetine cenderung menimbulkan gejala putus obat lebih kuat; fluoxetine bertahan jauh lebih lama di tubuh dan biasanya lebih ringan.';

  @override
  String get ssriMilestone7Title => 'Satu Minggu: Fase Akut Mulai Mereda';

  @override
  String get ssriMilestone7Description =>
      'Gejala fisik paling intens mulai mereda. Otak Anda menyesuaikan sinyal serotoninnya agar berfungsi tanpa obat. Tidur dan nafsu makan mulai stabil.';

  @override
  String get ssriMilestone14Title => '2 Minggu: Gejala Fisik Mereda';

  @override
  String get ssriMilestone14Description =>
      'Sebagian besar gejala fisik akut akibat penghentian obat sudah jauh berkurang atau mereda. Brain zaps, mual, dan pusing mulai menghilang. Kepekaan emosi masih dapat meningkat sementara otak terus menyesuaikan sistem serotoninnya.';

  @override
  String get ssriMilestone30Title => '1 Bulan: Emosi dan Energi Stabil';

  @override
  String get ssriMilestone30Description =>
      'Satu bulan adalah tonggak penting. Kualitas tidur membaik, energi mulai stabil, dan banyak orang merasakan suasana hati menemukan keseimbangan baru. Otak terus menyesuaikan kembali pengaturan serotonin alaminya.';

  @override
  String get ssriMilestone90Title => '3 Bulan: Kurva Putus Obat Berbalik';

  @override
  String get ssriMilestone90Description =>
      'Dalam uji ANTLER, selisih gejala putus obat setelah menghentikan antidepresan jangka panjang paling besar pada minggu ke-12 dan lebih kecil pada tindak lanjut berikutnya. Itu menjadikan tiga bulan sebagai titik balik nyata dalam perjalanan putus obat yang terukur.';

  @override
  String get ssriMilestone180Title => 'Enam Bulan: 65% Tetap Baik';

  @override
  String get ssriMilestone180Description =>
      'Dalam tindak lanjut enam bulan setelah penghentian antidepresan pada orang yang sedang remisi, 54 dari 83 peserta dengan data tindak lanjut — 65% — tetap dalam kondisi baik. Enam bulan adalah tonggak stabilitas jangka panjang yang nyata.';

  @override
  String get ssriMilestone365Title => 'Satu Tahun: Tonggak Besar';

  @override
  String get ssriMilestone365Description =>
      'Satu tahun penuh tanpa obat adalah tonggak besar. Dalam ANTLER, banyak pengguna antidepresan jangka panjang yang berhenti berhasil melewati 52 minggu tanpa kambuh, meski kekambuhan lebih sering terjadi setelah berhenti dibandingkan dengan terapi pemeliharaan. Jika setelah setahun kamu tetap baik-baik saja, itu kemajuan nyata yang layak dirayakan.';

  @override
  String get settingsShowSsriTracking => 'Tampilkan pelacakan SSRI';

  @override
  String get settingsNotifySsri => 'Beritahu kemajuan penghentian SSRI';

  @override
  String get addictionSnri => 'SNRI';

  @override
  String get snriPageTitle => 'Pemulihan SNRI';

  @override
  String get snriHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get snriHeaderNotStarted => 'Manfaat Mengurangi SNRI';

  @override
  String get snriSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get snriSubtitleNotStarted =>
      'Lihat apa yang terjadi saat Anda melakukan pengurangan bertahap';

  @override
  String get snriMilestone3Title => 'Hari 3: Puncak gejala putus obat';

  @override
  String get snriMilestone3Description =>
      'SNRI - khususnya venlafaxine (Effexor) - dikaitkan dengan beberapa sindrom penghentian antidepresan yang paling parah. Waktu paruh Venlafaxine yang sangat singkat (5 jam) berarti gejalanya bisa lebih intens dibandingkan kebanyakan SSRI. Gejala FINISH (perasaan seperti flu, insomnia, mual, ketidakseimbangan, gangguan sensorik, hiperarousal) mempengaruhi sistem serotonin dan norepinefrin secara bersamaan.';

  @override
  String get snriMilestone7Title => '1 Minggu: Dua sistem menyesuaikan';

  @override
  String get snriMilestone7Description =>
      'SNRI mempengaruhi reuptake serotonin dan norepinefrin. Kedua sistem melakukan penyesuaian secara bersamaan. Gejala fisik yang paling intens mulai mereda, namun mekanisme ganda berarti penyesuaian bisa terasa lebih kompleks dibandingkan dengan SSRI saja.';

  @override
  String get snriMilestone14Title => 'Dua Minggu: Gejala Fisik Memudar';

  @override
  String get snriMilestone14Description =>
      'Sebagian besar gejala fisik akut akibat penghentian obat sudah jauh berkurang. Sensasi seperti sengatan listrik di kepala, mual, dan pusing mulai mereda. Penyesuaian sistem norepinefrin masih dapat menimbulkan kecemasan atau perubahan tekanan darah; biasanya hal ini mereda dalam beberapa minggu berikutnya.';

  @override
  String get snriMilestone30Title => '1 Bulan: Norepinefrin stabil';

  @override
  String get snriMilestone30Description =>
      'Satu bulan menandai tonggak sejarah yang signifikan. Sistem serotonin dan norepinefrin secara aktif melakukan penyeimbangan kembali. Kualitas tidur dan tingkat energi menjadi stabil. Banyak orang merasakan peningkatan rentang emosi ketika efek obat terhadap penumpulan emosi mulai teratasi.';

  @override
  String get snriMilestone90Title => '3 Bulan: Masa putus obat terlewati';

  @override
  String get snriMilestone90Description =>
      'Putus obat SNRI biasanya mulai dalam beberapa hari dan berlangsung beberapa minggu. Pada hari ke-90, masa gejala yang umum itu sudah jauh terlewati — tonggak pemulihan yang nyata.';

  @override
  String get snriMilestone180Title => 'Enam Bulan: Pemulihan Neurologis';

  @override
  String get snriMilestone180Description =>
      'Enam bulan memungkinkan penyesuaian kembali sistem serotonin dan norepinefrin secara substansial. Sumbu HPA – yang dipengaruhi oleh SNRI melalui norepinefrin – menjadi normal. Banyak orang melaporkan peningkatan ketahanan terhadap stres sehari-hari pada saat ini.';

  @override
  String get snriMilestone365Title => 'Satu Tahun: Pemulihan Tercapai';

  @override
  String get snriMilestone365Description =>
      'Satu tahun menandai siklus lengkap pemulihan ganda serotonin-norepinefrin. Penelitian secara konsisten menunjukkan bahwa orang yang berhasil menghentikan SNRI di bawah pengawasan medis dan dengan dukungan psikologis akan mempertahankan hasil yang baik dalam satu tahun.';

  @override
  String get snriMilestone730Title => '2 Tahun: Langkah Mantap';

  @override
  String get snriMilestone730Description =>
      'Dua tahun sejak menyelesaikan penurunan dosis SNRI layak dirayakan. Pengalaman putus obat berbeda-beda, jadi peringatan ini menandai kemajuan yang bertahan, bukan batas pemulihan biologis untuk semua orang.';

  @override
  String get snriReferenceDay730 =>
      'Dua Tahun Setelah SNRI: Penanda Kemajuan\n\nSumber: Royal College of Psychiatrists — Menghentikan antidepresan\n\nAntidepresan umumnya tidak boleh dihentikan mendadak. Penurunan dosis perlu disesuaikan; duloxetine atau venlafaxine dapat memerlukan pengurangan lebih lambat selama berbulan-bulan atau lebih.\n\nPanduan tidak menetapkan batas pemulihan biologis dua tahun. Peringatan ini merayakan kemajuan yang bertahan.';

  @override
  String get snriMilestone1095Title => '3 Tahun: Kemajuan Bertahan';

  @override
  String get snriMilestone1095Description =>
      'Tiga tahun adalah rentang hidup yang berarti setelah penurunan dosis. Rayakan rutinitas, dukungan, dan pilihan yang menjaga kemajuanmu; ilmu kedokteran tidak menetapkan ambang pemulihan khusus pada tanggal ini.';

  @override
  String get snriReferenceDay1095 =>
      'Tiga Tahun Setelah SNRI: Kemajuan yang Bertahan\n\nSumber: Royal College of Psychiatrists — Menghentikan antidepresan\n\nPengalaman putus obat berbeda pada setiap orang. Kecepatan penurunan perlu mempertimbangkan individu, lama pengobatan, gejala sebelumnya, dan obat yang digunakan.\n\nTidak ada panduan klinis yang menetapkan tiga tahun sebagai tenggat pemulihan universal; tonggak ini mengakui kemajuanmu.';

  @override
  String get snriMilestone1460Title => '4 Tahun: Kekuatan Bertumbuh';

  @override
  String get snriMilestone1460Description =>
      'Empat tahun mencerminkan kemajuan tahan lama yang dibangun dari waktu ke waktu. Pengalamanmu bersifat individual, dan tonggak ini menghargai apa yang telah kamu pertahankan tanpa mengklaim jadwal neurologis yang tetap.';

  @override
  String get snriReferenceDay1460 =>
      'Empat Tahun Setelah SNRI: Kemajuan Jangka Panjang\n\nSumber: Royal College of Psychiatrists — Menghentikan antidepresan\n\nRoyal College menjelaskan bahwa putus antidepresan bervariasi dan menganjurkan penurunan bertahap yang disesuaikan. Duloxetine dan venlafaxine memiliki risiko gejala putus obat lebih tinggi.\n\nBukti itu tidak menciptakan tonggak neurologis empat tahun; hari ini merayakan kemajuan yang bertahan.';

  @override
  String get snriMilestone1825Title => '5 Tahun: Lima Tahun Tercapai';

  @override
  String get snriMilestone1825Description =>
      'Lima tahun adalah tonggak pribadi yang besar. Ini merayakan kemajuan jangka panjang setelah berhenti dari SNRI sambil mengakui bahwa putus obat dan pemulihan tidak mengikuti satu jadwal yang sama.';

  @override
  String get snriReferenceDay1825 =>
      'Lima Tahun Setelah SNRI: Tonggak Lima Tahun\n\nSumber: Royal College of Psychiatrists — Menghentikan antidepresan\n\nPanduan berfokus pada penurunan dosis yang aman dan individual serta penanganan gejala, bukan satu jadwal pemulihan untuk semua orang.\n\nTidak ada batas pemulihan SNRI lima tahun berbasis bukti. Meski begitu, lima tahun tetap merupakan peringatan pribadi yang bermakna.';

  @override
  String get settingsShowSnriTracking => 'Tampilkan pelacakan SNRI';

  @override
  String get settingsNotifySnri => 'Beritahu SNRI tentang kemajuan penghentian';

  @override
  String get addictionTca => 'TCA';

  @override
  String get tcaPageTitle => 'Pemulihan TCA';

  @override
  String get tcaHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get tcaHeaderNotStarted => 'Manfaat Pengurangan TCA';

  @override
  String get tcaSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get tcaSubtitleNotStarted =>
      'Lihat apa yang terjadi saat Anda melakukan pengurangan bertahap';

  @override
  String get tcaMilestone3Title => 'Hari ke-3: Rebound Kolinergik';

  @override
  String get tcaMilestone3Description =>
      'Berhenti TCA dapat memicu sindrom putus obat yang nyata, dengan aktivitas kolinergik berlebih sebagai salah satu mekanisme yang diusulkan. Mual, diare, sakit perut, insomnia, cemas, gelisah, dan sakit kepala dapat muncul lebih awal—terutama setelah berhenti mendadak atau taper yang terlalu cepat. Hari ke-3 adalah pencapaian; waktu dan intensitas gejala berbeda-beda.';

  @override
  String get tcaMilestone7Title => 'Satu Minggu: Tahap Pertama Terlewati';

  @override
  String get tcaMilestone7Description =>
      'Gejala putus antidepresan biasanya mulai dalam beberapa hari dan sering berlangsung beberapa minggu. Setelah satu minggu, mual, keringat, gangguan tidur, jantung berdebar, dan pusing masih bisa terasa. Tujuh hari adalah kemajuan nyata, dan pemulihan dapat terus bergerak dengan waktu yang berbeda-beda.';

  @override
  String get tcaMilestone14Title => 'Dua Minggu: Fase Akut Mulai Reda';

  @override
  String get tcaMilestone14Description =>
      'Gejala khas penghentian antidepresan seperti mual, insomnia, gangguan keseimbangan, gangguan sensorik, dan hiperaktivasi biasanya berlangsung satu hingga dua minggu. Pada hari ke-14, banyak orang mencapai ujung fase akut ini.';

  @override
  String get tcaMilestone30Title => 'Satu Bulan: Fase Akut Sudah Reda';

  @override
  String get tcaMilestone30Description =>
      'Gejala penghentian antidepresan yang khas biasanya berlangsung satu hingga dua minggu. Pada hari ke-30, kebanyakan orang sudah melewati fase akut itu; gejala seperti flu, mual, gangguan keseimbangan, insomnia, gangguan sensorik, dan hiperaktivasi biasanya sudah mereda atau hilang.';

  @override
  String get tcaMilestone90Title => 'Tiga Bulan: Fase Akut Terlewati';

  @override
  String get tcaMilestone90Description =>
      'Gejala penghentian antidepresan yang khas biasanya berlangsung satu hingga dua minggu. Pada hari ke-90, Anda sudah lebih dari sepuluh minggu melewati batas atas fase akut yang umum itu; gejala seperti flu, mual, gangguan keseimbangan, insomnia, gangguan sensorik, dan hiperaktivasi biasanya sudah lama mereda atau hilang.';

  @override
  String get tcaMilestone180Title => 'Enam Bulan: Mayoritas Tanpa Kambuh';

  @override
  String get tcaMilestone180Description =>
      'Pada orang yang menghentikan antidepresan setelah pengobatan depresi mayor, meta-analisis 35 uji menemukan angka kekambuhan gabungan 34,8% pada enam bulan—sekitar 65% tetap tanpa kambuh. Itu adalah rentang stabilitas yang sangat besar.';

  @override
  String get tcaMilestone365Title => 'Satu Tahun: Mayoritas Tanpa Kambuh';

  @override
  String get tcaMilestone365Description =>
      'Pada orang yang menghentikan antidepresan setelah pengobatan depresi mayor, meta-analisis 35 uji menemukan angka kekambuhan gabungan 45,12% pada 12 bulan—sekitar 55% tetap tanpa kambuh selama setahun penuh. Itu adalah tonggak besar stabilitas jangka panjang.';

  @override
  String get tcaMilestone730Title => '2 Tahun: Landasan Kokoh';

  @override
  String get tcaMilestone730Description =>
      'Dua tahun sejak menyelesaikan penurunan dosis TCA adalah tonggak besar. Pengalaman putus obat berbeda pada setiap orang, jadi pencapaian ini merayakan kemajuan yang bertahan tanpa mengklaim batas akhir biologis yang berlaku untuk semua.';

  @override
  String get tcaReferenceDay730 =>
      'Dua Tahun Setelah TCA: Kemajuan Berkelanjutan\n\nSumber: NICE NG222 — Depression in adults: treatment and management\n\nNICE secara jelas memasukkan TCA sebagai antidepresan yang dapat menimbulkan gejala putus obat. Pengalaman berbeda pada tiap orang dan penurunan dosis sebaiknya dilakukan bertahap sesuai kebutuhan individu.\n\nPedoman tidak menetapkan ambang biologis dua tahun. Peringatan ini merayakan dua tahun kemajuan yang bertahan tanpa membuat garis akhir universal.';

  @override
  String get tcaMilestone1095Title => '3 Tahun: Kemajuan Terjaga';

  @override
  String get tcaMilestone1095Description =>
      'Tiga tahun menunjukkan kemajuan yang terus terjaga. Pedoman klinis tidak menetapkan titik akhir pemulihan TCA khusus pada tanggal ini; yang layak dirayakan adalah kestabilan, kebiasaan, dan pilihan yang dipertahankan selama bertahun-tahun.';

  @override
  String get tcaReferenceDay1095 =>
      'Tiga Tahun Setelah TCA: Kemajuan Terjaga\n\nSumber: NICE NG222 — Depression in adults: treatment and management\n\nNICE secara jelas memasukkan TCA sebagai antidepresan yang dapat menimbulkan gejala putus obat. Pengalaman berbeda pada tiap orang dan penurunan dosis sebaiknya dilakukan bertahap sesuai kebutuhan individu.\n\nPedoman tidak menetapkan tiga tahun sebagai tenggat pemulihan universal. Tonggak ini menghargai kestabilan dan kemajuan yang dipertahankan selama tiga tahun.';

  @override
  String get tcaMilestone1460Title => '4 Tahun: Kemajuan Bertahan';

  @override
  String get tcaMilestone1460Description =>
      'Empat tahun mencerminkan kemajuan tahan lama yang dibangun seiring waktu. Pengalaman setelah berhenti TCA bersifat individual, dan tonggak ini menghargai apa yang telah dipertahankan tanpa membuat jadwal neurologis yang kaku.';

  @override
  String get tcaReferenceDay1460 =>
      'Empat Tahun Setelah TCA: Kemajuan Jangka Panjang\n\nSumber: NICE NG222 — Depression in adults: treatment and management\n\nNICE secara jelas memasukkan TCA sebagai antidepresan yang dapat menimbulkan gejala putus obat. Pengalaman berbeda pada tiap orang dan penurunan dosis sebaiknya dilakukan bertahap sesuai kebutuhan individu.\n\nTidak ada ambang biologis empat tahun dalam pedoman tersebut. Empat tahun tetap menjadi penanda bermakna untuk kemajuan jangka panjang.';

  @override
  String get tcaMilestone1825Title => '5 Tahun: Kemajuan Berkelanjutan';

  @override
  String get tcaMilestone1825Description =>
      'Lima tahun adalah peringatan pribadi yang besar. Ini menandai perubahan yang bertahan setelah berhenti TCA sambil mengakui bahwa putus obat dan pemulihan tidak mengikuti satu jadwal yang sama untuk semua orang.';

  @override
  String get tcaReferenceDay1825 =>
      'Lima Tahun Setelah TCA: Peringatan Besar\n\nSumber: NICE NG222 — Depression in adults: treatment and management\n\nNICE secara jelas memasukkan TCA sebagai antidepresan yang dapat menimbulkan gejala putus obat. Pengalaman berbeda pada tiap orang dan penurunan dosis sebaiknya dilakukan bertahap sesuai kebutuhan individu.\n\nBukti tidak menetapkan ambang pemulihan TCA pada lima tahun. Lima tahun tetap menjadi peringatan pribadi yang besar dan penanda perubahan yang bertahan.';

  @override
  String get settingsShowTcaTracking => 'Tampilkan pelacakan TCA';

  @override
  String get settingsNotifyTca => 'Beritahu kemajuan penghentian TCA';

  @override
  String get addictionMaoi => 'MAOI';

  @override
  String get maoiPageTitle => 'Pemulihan MAOI';

  @override
  String get maoiHeaderStarted => 'Perjalanan Pemulihan Anda';

  @override
  String get maoiHeaderNotStarted => 'Manfaat Mengurangi MAOI';

  @override
  String get maoiSubtitleStarted =>
      'Lacak kemajuan Anda dan rayakan setiap pencapaian';

  @override
  String get maoiSubtitleNotStarted =>
      'Lihat apa yang terjadi saat Anda melakukan pengurangan bertahap';

  @override
  String get maoiMilestone3Title => 'Hari 3: Risiko Tertinggi';

  @override
  String get maoiMilestone3Description =>
      'MAOI membawa risiko penghentian paling serius dibandingkan kelas antidepresan mana pun. Penghentian penggunaan secara tiba-tiba – terutama phenelzine dan tranylcypromine – dapat menyebabkan agitasi parah, kebingungan, halusinasi, mioklonus, dan hipertermia. Jika Anda mengalami gejala-gejala ini, segera dapatkan bantuan medis. MAOI bekerja dengan menonaktifkan enzim MAO secara permanen; pemulihan membutuhkan tubuh untuk mensintesis enzim baru, sebuah proses yang memakan waktu sekitar 14 hari.';

  @override
  String get maoiMilestone7Title => '1 Minggu: Sintesis MAO';

  @override
  String get maoiMilestone7Description =>
      'MAOI secara permanen menghancurkan molekul enzim MAO; pemulihan membutuhkan sintesis enzim yang sama sekali baru. Dalam satu minggu, sekitar 50% aktivitas MAO normal mungkin telah pulih. Gejala penghentian akut yang parah (delirium, mioklonus, hipertermia) berkurang secara signifikan. Pengawasan medis yang ketat tetap penting.';

  @override
  String get maoiMilestone14Title => '2 Minggu: Aktivitas MAO Pulih';

  @override
  String get maoiMilestone14Description =>
      'Dua minggu adalah jangka waktu klinis standar untuk pemulihan enzim MAO setelah penghentian. Sekitar hari ke 14, aktivitas MAO-A dan MAO-B sebagian besar pulih dan metabolisme tyramine normal kembali terbentuk. Pembatasan diet yang diperlukan selama pengobatan MAOI biasanya dapat dilonggarkan dengan berkonsultasi dengan dokter yang meresepkan Anda.';

  @override
  String get maoiMilestone30Title => '1 Bulan: Sistem Otak Seimbang';

  @override
  String get maoiMilestone30Description =>
      'Satu bulan setelah menghentikan MAOI, enzim MAO aktif kembali dan otak menangani serotonin, noradrenalin, dopamin, dan tyramine secara alami. Periode interaksi makanan dan obat khusus telah berakhir, namun Anda tetap harus memberi tahu pemberi resep tentang penggunaan MAOI sebelumnya.';

  @override
  String get maoiMilestone90Title => 'Tiga Bulan: Normalisasi Kimia Otak';

  @override
  String get maoiMilestone90Description =>
      'Tiga bulan memberikan suasana hati dan sistem energi otak waktu yang cukup untuk menyesuaikan diri setelah MAOI. Suasana hati, energi, dan pemikiran jernih menjadi stabil saat otak menangani kembali bahan kimia ini secara alami.';

  @override
  String get maoiMilestone180Title => 'Enam Bulan: Pemulihan Jangka Panjang';

  @override
  String get maoiMilestone180Description =>
      'Enam bulan mewakili periode substansial fungsi monoamina alami. Populasi reseptor serotonin, norepinefrin, dan dopamin telah kembali normal. Jalur phenethylamine (PEA) yang juga terpengaruh oleh MAOI telah pulih ke tingkat alami – sebuah aspek pemulihan yang sering diabaikan dan berkontribusi pada normalisasi emosional.';

  @override
  String get maoiMilestone365Title => 'Satu Tahun: Pemulihan Tercapai';

  @override
  String get maoiMilestone365Description =>
      'Satu tahun setelah menghentikan MAOI memberi otak dan tubuh satu tahun penuh tanpa obat. Suasana hati, energi, pemikiran jernih, dan regulasi kimia otak yang normal memiliki waktu yang cukup lama untuk pulih dan tenang.';

  @override
  String get settingsShowMaoiTracking => 'Tampilkan pelacakan MAOI';

  @override
  String get settingsNotifyMaoi =>
      'Beritahu MAOI mengenai kemajuan penghentiannya';

