  @override
  String vapingStreakTitle(int days) {
    return 'Bebas vape: hari ke-$days';
  }

  @override
  String get vapingDay1Description =>
      'Hari pertama tanpa vape. Jika vape-mu mengandung nikotin, ngidam, mudah marah, gelisah, suasana hati turun, sulit tidur, atau susah fokus bisa menjadi gejala putus nikotin — bukan alasan untuk memberinya nikotin lagi. Apa pun itu, kamu sudah mulai memutus siklus vaping.';

  @override
  String get vapingDay3Description =>
      'Tiga hari bebas vape. Dalam studi klinis pada mantan perokok yang memakai rokok elektronik setiap hari, skor rata-rata gejala putus mencapai puncak pada hari ke-1 atau ke-2, lalu menurun selama empat hari abstinensi berikutnya. Kamu sekarang sudah melewati jendela puncak awal yang terlihat dalam studi itu; ngidam masih bisa muncul, tapi bukan dia yang memegang kendali.';

  @override
  String get vapingDay7Description =>
      'Tujuh hari penuh tanpa menghirup aerosol vape. Itu berarti seminggu tanpa paparan baru dari vaping terhadap nikotin, partikel ultrahalus, logam berat, senyawa organik volatil, atau zat berbahaya lain yang dapat dibawa aerosol. Rentetan bersih — lanjutkan.';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days hari tanpa mengambil satu isapan aerosol vape lagi. Itu $days hari tanpa paparan baru dari vaping terhadap zat berbahaya yang dapat dibawa aerosol. Jika vape-mu mengandung nikotin, itu juga $days hari tanpa memperkuat ketergantungan tersebut. Rentetan besar — terus maju.';
  }

  @override
  String get vapingMilestone730Title => 'Dua Tahun: Makin Kuat';

  @override
  String get vapingMilestone730Description =>
      'Dua tahun bebas vape. CDC menyatakan ketergantungan nikotin dapat membuat berhenti terasa sulit dan dampak kesehatan jangka panjang vaping masih diteliti. Kemenangan yang benar-benar dapat dipastikan adalah rentetannya sendiri: 730 hari tanpa kembali ke vape.';

  @override
  String get vapingMilestone1095Title => 'Tiga Tahun: Momentum Kuat';

  @override
  String get vapingMilestone1095Description =>
      'Tiga tahun bebas vape. Kamu mempertahankan perubahan yang sulit selama 1.095 hari. CDC tidak menetapkan ambang pemulihan biologis tiga tahun, jadi rayakan hal yang memang didukung bukti: kebebasan berkelanjutan dari vaping.';

  @override
  String get vapingMilestone1460Title => 'Empat Tahun: Pijakan Kokoh';

  @override
  String get vapingMilestone1460Description =>
      'Empat tahun bebas vape. Itu 1.460 hari tanpa memperkuat kembali kebiasaan vaping. Ilmu pengetahuan belum menetapkan garis waktu pemulihan jangka panjang yang berlaku untuk semua orang, tetapi perubahan tahan lama ini nyata dan layak dirayakan.';

  @override
  String get vapingMilestone1825Title => 'Lima Tahun: Setengah Dekade';

  @override
  String get vapingMilestone1825Description =>
      'Lima tahun bebas vape. Setengah dekade tanpa kembali ke vaping adalah pencapaian jangka panjang yang besar. Bukti CDC tidak menjadikan lima tahun sebagai titik akhir medis; tonggaknya adalah perubahan berkelanjutan yang kamu bangun.';

  @override
  String get vapingLongTermReference =>
      'Vaping, Berhenti, dan Bukti Jangka Panjang\n\nSumber: CDC — Vaping and Quitting; CDC — Health Effects of Vaping\n\nCDC menyatakan bahwa orang yang vaping dapat mengalami ketergantungan nikotin, berhenti dapat memicu gejala putus nikotin, dan cara terbaik membantu orang berhenti vaping masih diteliti. CDC juga menyebut dampak kesehatan jangka panjang rokok elektronik masih dipelajari.\n\nSumber-sumber ini tidak menetapkan ambang pemulihan biologis pada dua, tiga, empat, atau lima tahun setelah berhenti vaping. Karena itu Quitter memperlakukan tanggal-tanggal ini sebagai hari jadi kemajuan bebas vape yang berkelanjutan, bukan titik akhir medis.';

  @override
  String get vapingWithdrawalReference =>
      'Abstinensi rokok elektronik dan gejala putus\n\nSumber: Hughes dkk., Nicotine & Tobacco Research (2020)\n\nPada 109 mantan perokok yang memakai rokok elektronik setiap hari, enam hari abstinensi yang dikonfirmasi secara biologis meningkatkan gejala putus nikotin dan rasa ingin memakai. Gejalanya mengikuti pola naik-turun khas putus zat, dengan peningkatan kuat pada dua hari pertama abstinensi. Studi ini mendukung bahwa putus dari rokok elektronik itu nyata, tetapi tidak menetapkan jadwal pemulihan universal dari hari ke hari.';

  @override
  String get vapingHealthReference =>
      'Paparan dari vaping\n\nSumber: CDC — Health Effects of Vaping\n\nCDC menyatakan sebagian besar rokok elektronik mengandung nikotin yang membuat ketagihan. Aerosol vape dapat mengandung nikotin, bahan kimia penyebab kanker, logam berat seperti nikel, timah, dan timbal, partikel sangat kecil yang masuk jauh ke paru-paru, senyawa organik volatil, serta beberapa bahan perasa berbahaya. Putus nikotin dapat menyebabkan mudah marah, cemas atau gelisah, suasana hati turun, masalah tidur dan konsentrasi, lapar, serta ngidam; gejala ini memudar seiring waktu. Efek jangka panjang vaping masih diteliti, jadi Quitter merayakan abstinensi nyata alih-alih meminjam jadwal rokok untuk karbon monoksida, tar, kanker, atau risiko jantung.';

  @override
  String get adderallMilestone730Title => 'Dua Tahun: Perubahan Bertahan';

  @override
  String get adderallMilestone730Description =>
      'Dua tahun tanpa menyalahgunakan Adderall adalah perubahan yang bertahan, bukan sekadar rentetan singkat. Anda telah membangun rutinitas dan pilihan yang dapat terus membawa Anda maju.';

  @override
  String get adderallReferenceDay730 =>
      'Dua Tahun Tanpa Penyalahgunaan Adderall: Kemajuan yang Bertahan\n\nSumber: SAMHSA, Treatment of Stimulant Use Disorders\n\nPanduan SAMHSA mencakup stimulan jenis amfetamin, termasuk penyalahgunaan stimulan resep, dan mendukung perawatan berbasis bukti untuk pemulihan. Panduan ini tidak menetapkan “reset” biologis pada dua tahun.\n\nDua tahun tetap merupakan pencapaian besar. Anda telah mempertahankan perubahan dalam waktu yang panjang; rayakan kestabilan yang telah dibangun dan teruskan hal-hal yang terbukti membantu.';

  @override
  String get adderallMilestone1095Title => 'Tiga Tahun: Landasan Kuat';

  @override
  String get adderallMilestone1095Description =>
      'Tiga tahun adalah kemajuan jangka panjang yang Anda raih hari demi hari. Terus jaga kehidupan, kebiasaan, dan dukungan yang membuatnya mungkin.';

  @override
  String get adderallReferenceDay1095 =>
      'Tiga Tahun Tanpa Penyalahgunaan Adderall: Pemulihan yang Terus Melaju\n\nSumber: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA mendukung pengobatan berbasis bukti dan pemulihan jangka panjang dari gangguan penggunaan stimulan, termasuk masalah yang melibatkan stimulan resep. Panduan ini tidak menyatakan bahwa perubahan otak tertentu selesai pada tiga tahun.\n\nTiga tahun mencerminkan perubahan yang bertahan melewati hari biasa maupun hari sulit. Pertahankan rutinitas, hubungan, dan dukungan yang membantu Anda sampai di titik ini.';

  @override
  String get adderallMilestone1460Title => 'Empat Tahun: Akar Mendalam';

  @override
  String get adderallMilestone1460Description =>
      'Empat tahun menunjukkan konsistensi yang luar biasa. Tonggak ini merayakan kebebasan yang terus terjaga dari penyalahgunaan dan kestabilan yang Anda bangun di sekitarnya.';

  @override
  String get adderallReferenceDay1460 =>
      'Empat Tahun Tanpa Penyalahgunaan Adderall: Perubahan Jangka Panjang dalam Kehidupan Nyata\n\nSumber: SAMHSA, Treatment of Stimulant Use Disorders\n\nPanduan SAMHSA berfokus pada perawatan dan dukungan yang membantu orang mencapai pemulihan jangka panjang. Panduan ini tidak menetapkan garis akhir medis pada empat tahun, jadi tonggak ini tentang kemajuan yang bertahan, bukan janji kesehatan yang dibuat-buat.\n\nEmpat tahun menunjukkan konsistensi dalam rentang waktu yang benar-benar panjang. Jaga struktur dan orang-orang yang membantu kemajuan Anda tetap stabil.';

  @override
  String get adderallMilestone1825Title => 'Lima Tahun: Kemenangan Besar';

  @override
  String get adderallMilestone1825Description =>
      'Lima tahun layak dirayakan. Anda telah mempertahankan arah yang berbeda selama 1.825 hari dan membangun bukti bertahun-tahun bahwa perubahan dapat bertahan.';

  @override
  String get adderallReferenceDay1825 =>
      'Lima Tahun Tanpa Penyalahgunaan Adderall: Setengah Dekade Kemajuan\n\nSumber: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA mengakui pemulihan jangka panjang sebagai tujuan penting perawatan gangguan penggunaan stimulan. Panduannya tidak menjanjikan peristiwa biologis khusus pada lima tahun, dan tonggak ini tidak memerlukannya untuk berarti.\n\nLima tahun adalah 1.825 hari mempertahankan arah yang berbeda. Itu adalah pengalaman hidup yang kuat bahwa perubahan Anda dapat bertahan. Rayakan, lalu teruskan hal-hal yang membuatnya mungkin.';

  @override
  String get alcoholMilestone730Title => 'Dua Tahun: Kemajuan Mantap';

  @override
  String get alcoholMilestone730Description =>
      'Dua tahun tanpa alkohol berada dalam rentang satu hingga lima tahun yang NIAAA gunakan sebagai durasi berkelanjutan dalam riset pemulihan. Ini pencapaian besar yang layak dijaga.';

  @override
  String get alcoholReferenceDay730 =>
      'Dua Tahun Tanpa Alkohol: Kemajuan Mantap\n\nSumber: NIAAA, Recovery Research Definitions\n\nNIAAA memakai satu hingga lima tahun sebagai kategori durasi berkelanjutan untuk remisi gangguan penggunaan alkohol dan berhentinya konsumsi berat yang dipertahankan dari waktu ke waktu. Tidak minum melampaui ambang konsumsi, tetapi pantang saja tidak membuktikan semua kriteria remisi klinis.\n\nDua tahun berarti 730 hari mempertahankan perubahan. Rayakan konsistensi itu dan terus jaga rutinitas, hubungan, dan dukungan yang membuatnya bertahan.';

  @override
  String get alcoholMilestone1095Title => 'Tiga Tahun: Landasan Kuat';

  @override
  String get alcoholMilestone1095Description =>
      'Tiga tahun tanpa alkohol adalah 1.095 hari perubahan jangka panjang. NIAAA menempatkan durasi ini dalam rentang berkelanjutan riset pemulihan.';

  @override
  String get alcoholReferenceDay1095 =>
      'Tiga Tahun Tanpa Alkohol: Landasan Kuat\n\nSumber: NIAAA, Recovery Research Definitions\n\nNIAAA memakai satu hingga lima tahun sebagai kategori durasi berkelanjutan untuk remisi gangguan penggunaan alkohol dan berhentinya konsumsi berat. NIAAA tidak menyatakan ada reset biologis khusus pada tahun ketiga.\n\nTiga tahun berarti 1.095 hari memperkuat pola yang berbeda. Konsistensi itu bermakna dengan sendirinya, dan dukungan yang membawamu sampai sini layak dipertahankan.';

  @override
  String get alcoholMilestone1460Title => 'Empat Tahun: Perubahan Awet';

  @override
  String get alcoholMilestone1460Description =>
      'Empat tahun tanpa alkohol menunjukkan perubahan yang bertahan pada skala waktu yang benar-benar panjang. Pencapaiannya adalah daya tahan itu sendiri, bukan tenggat medis yang dibuat-buat.';

  @override
  String get alcoholReferenceDay1460 =>
      'Empat Tahun Tanpa Alkohol: Perubahan Awet\n\nSumber: NIAAA, Recovery Research Definitions\n\nEmpat tahun masih berada dalam rentang berkelanjutan satu hingga lima tahun yang NIAAA gunakan dalam riset. Kerangka ini membahas remisi dan berhentinya konsumsi berat yang dipertahankan, bukan klaim bahwa tubuh atau otak setiap orang mencapai garis akhir yang sama pada tanggal yang sama.\n\nEmpat tahun tanpa alkohol berarti perubahan yang bertahan melewati hari biasa, stres, musim, dan berbagai tonggak. Daya tahannya sendiri adalah pencapaian.';

  @override
  String get alcoholMilestone1825Title => 'Lima Tahun: Tonggak Besar';

  @override
  String get alcoholMilestone1825Description =>
      'Lima tahun tanpa alkohol mencapai ujung atas rentang berkelanjutan satu hingga lima tahun NIAAA. Kategori stabil baru dimulai setelah lebih dari lima tahun.';

  @override
  String get alcoholReferenceDay1825 =>
      'Lima Tahun Tanpa Alkohol: Tonggak Besar\n\nSumber: NIAAA, Recovery Research Definitions\n\nNIAAA menyebut satu hingga lima tahun sebagai kategori durasi berkelanjutan dan menyebut lebih dari lima tahun sebagai stabil. Jadi tepat lima tahun masih berada di ujung rentang berkelanjutan. Kerangka ini juga mencakup remisi gejala AUD, sehingga pantang saja tidak boleh dianggap sebagai diagnosis klinis.\n\nLima tahun tanpa alkohol adalah 1.825 hari perubahan yang dipertahankan. Setengah dekade pantas mendapat penghargaan nyata tanpa menciptakan garis akhir medis yang tidak didukung bukti.';

  @override
  String get ghbMilestone730Title => 'Dua Tahun: Kemajuan Bertahan';

  @override
  String get ghbMilestone730Description =>
      'Dua tahun tanpa GHB berarti 730 hari perubahan yang bertahan. SAMHSA menggambarkan pemulihan sebagai proses berkelanjutan dan pribadi, jadi tonggak ini merayakan konsistensi, bukan garis akhir medis yang berlaku untuk semua.';

  @override
  String get ghbReferenceDay730 =>
      'Dua Tahun Tanpa GHB: Kemajuan Bertahan\n\nSumber: SAMHSA, Pemulihan dan Dukungan Pemulihan\n\nSAMHSA menggambarkan pemulihan sebagai proses perubahan yang berkelanjutan dan pribadi, tanpa menetapkan titik akhir biologis khusus GHB pada peringatan tahun ini.\n\nDua tahun berarti 730 hari mempertahankan arah yang berbeda. Konsistensi serta orang, rutinitas, dan dukungan yang menjaganya patut dihargai.';

  @override
  String get ghbMilestone1095Title => 'Tiga Tahun: Pijakan Lebih Kuat';

  @override
  String get ghbMilestone1095Description =>
      'Tiga tahun tanpa GHB berarti 1.095 hari perubahan yang dipertahankan. Pemulihan bersifat pribadi; tonggak ini menghargai kestabilan yang dibangun, bukan tenggat biologis buatan.';

  @override
  String get ghbReferenceDay1095 =>
      'Tiga Tahun Tanpa GHB: Pijakan Lebih Kuat\n\nSumber: SAMHSA, Pemulihan dan Dukungan Pemulihan\n\nSAMHSA menggambarkan pemulihan sebagai proses perubahan yang berkelanjutan dan pribadi, tanpa menetapkan titik akhir biologis khusus GHB pada peringatan tahun ini.\n\nTiga tahun berarti 1.095 hari perubahan yang dipertahankan. Ini merupakan rekam jejak kestabilan yang besar dan perlindungan terhadap hal-hal yang menopang pemulihan.';

  @override
  String get ghbMilestone1460Title => 'Empat Tahun: Perubahan Bertahan';

  @override
  String get ghbMilestone1460Description =>
      'Empat tahun tanpa GHB berarti 1.460 hari perubahan yang bertahan. Pencapaiannya ada pada daya tahan itu sendiri serta kebiasaan, hubungan, dan dukungan yang menjaganya.';

  @override
  String get ghbReferenceDay1460 =>
      'Empat Tahun Tanpa GHB: Perubahan Bertahan\n\nSumber: SAMHSA, Pemulihan dan Dukungan Pemulihan\n\nSAMHSA menggambarkan pemulihan sebagai proses perubahan yang berkelanjutan dan pribadi, tanpa menetapkan titik akhir biologis khusus GHB pada peringatan tahun ini.\n\nEmpat tahun berarti 1.460 hari membawa perubahan melewati kehidupan sehari-hari. Daya tahan itu sendiri merupakan pencapaian.';

  @override
  String get ghbMilestone1825Title => 'Lima Tahun: Tonggak Besar';

  @override
  String get ghbMilestone1825Description =>
      'Lima tahun tanpa GHB berarti setengah dekade perubahan yang dipertahankan. SAMHSA memandang pemulihan sebagai proses berkelanjutan, sehingga 1.825 hari layak dirayakan sebagai tonggak tersendiri.';

  @override
  String get ghbReferenceDay1825 =>
      'Lima Tahun Tanpa GHB: Tonggak Besar\n\nSumber: SAMHSA, Pemulihan dan Dukungan Pemulihan\n\nSAMHSA menggambarkan pemulihan sebagai proses perubahan yang berkelanjutan dan pribadi, tanpa menetapkan titik akhir biologis khusus GHB pada peringatan tahun ini.\n\nLima tahun berarti 1.825 hari perubahan yang dipertahankan. Setengah dekade komitmen berulang pantas mendapat penghargaan nyata.';

  @override
  String get inhalantsMilestone1095Title => 'Tiga tahun: pulih makin kuat';

  @override
  String get inhalantsMilestone1095Description =>
      'Tiga tahun tanpa inhalansia adalah kemajuan yang bertahan. Riset mendukung pemulihan jangka panjang tanpa menetapkan batas biologis khusus pada tahun ketiga.';

  @override
  String get inhalantsMilestone1460Title => 'Empat tahun: langkah mantap';

  @override
  String get inhalantsMilestone1460Description =>
      'Empat tahun adalah rentang pemulihan penting lainnya. Bukti mendukung abstinensi berkelanjutan, bukan garis akhir universal pemulihan otak pada tahun keempat.';

  @override
  String get inhalantsMilestone1825Title => 'Lima tahun: fondasi kuat';

  @override
  String get inhalantsMilestone1825Description =>
      'Lima tahun menandai kemajuan tahan lama yang layak dirayakan. Abstinensi jangka panjang dapat mendukung pemulihan, sementara hasil bergantung pada jenis dan beratnya cedera sebelumnya.';

  @override
  String get inhalantsReferenceDay1095 =>
      'Tiga tahun tanpa inhalansia\n\nSumber: Cairney dkk., “Studi prospektif perubahan neurokognitif 15 tahun setelah penyalahgunaan inhalansia kronis”, Addiction (2013), PubMed\n\nMelampaui dua tahun\nStudi menemukan pemulihan besar setelah dua tahun abstinensi pada peserta tanpa ensefalopati timbal dan mengikuti kohort yang sama hingga 15 tahun. Tidak ada ambang biologis khusus yang ditetapkan pada tahun ketiga.\n\nTiga tahun kemajuan\nTiga tahun menandai abstinensi yang bertahan. Pemulihan jangka panjang dapat berlanjut, sedangkan hasil dipengaruhi paparan dan cedera sebelumnya; ensefalopati timbal dapat meninggalkan gangguan menetap.';

  @override
  String get inhalantsReferenceDay1460 =>
      'Empat tahun tanpa inhalansia\n\nSumber: Cairney dkk., “Studi prospektif perubahan neurokognitif 15 tahun setelah penyalahgunaan inhalansia kronis”, Addiction (2013), PubMed\n\nPemulihan jangka panjang\nPada kelompok tanpa ensefalopati timbal, sebagian besar skor telah normal setelah dua tahun dan kohort dinilai lagi pada 15 tahun. Publikasi tidak menetapkan peristiwa pemulihan khusus pada tahun keempat.\n\nEmpat tahun berjarak\nEmpat tahun menambah satu tahun penuh abstinensi yang bertahan dan memperkuat dasar pemulihan. Hasil dapat berbeda, terutama bila paparan sebelumnya menimbulkan cedera neurologis berat.';

  @override
  String get inhalantsReferenceDay1825 =>
      'Lima tahun tanpa inhalansia\n\nSumber: Cairney dkk., “Studi prospektif perubahan neurokognitif 15 tahun setelah penyalahgunaan inhalansia kronis”, Addiction (2013), PubMed\n\nTonggak jangka panjang\nStudi mendukung kemungkinan pemulihan neurologis dan kognitif yang besar melalui abstinensi jangka panjang bila ensefalopati timbal tidak ada. Penilaian dilakukan pada dua dan 15 tahun, sehingga lima tahun bukan garis akhir biologis universal.\n\nLima tahun terbangun\nLima tahun adalah kemajuan tahan lama dan rentang hidup yang panjang tanpa inhalansia. Bukti mendukung pemulihan jangka panjang sambil mengakui bahwa cedera berat terkait timbal dapat menetap.';

  @override
